(window.QDATA=window.QDATA||{})[10]={"s":10,"ar":"يونس","tl":"Yunus","n":109,"place":"makkah","bism":true,"mean":{"en":"Jonah","ur":"یونس","hi":"यूनुस"},"v":[{"a":1,"ar":" الٓر ۚ تِلْكَ ءَايَـٰتُ ٱلْكِتَـٰبِ ٱلْحَكِيمِ","en":"Alif, Lām, Rā. These are the verses of the wise Book.","ur":"آلرا ۔ یہ بڑی دانائی کی کتاب کی آیتیں ہیں","hi":"अलिफ़, लाम, रा। ये पूर्ण हिकमत वाली किताब की आयतें हैं।"},{"a":2,"ar":"أَكَانَ لِلنَّاسِ عَجَبًا أَنْ أَوْحَيْنَآ إِلَىٰ رَجُلٍ مِّنْهُمْ أَنْ أَنذِرِ ٱلنَّاسَ وَبَشِّرِ ٱلَّذِينَ ءَامَنُوٓا۟ أَنَّ لَهُمْ قَدَمَ صِدْقٍ عِندَ رَبِّهِمْ ۗ قَالَ ٱلْكَـٰفِرُونَ إِنَّ هَـٰذَا لَسَـٰحِرٌ مُّبِينٌ","en":"Have the people been amazed that We revealed [revelation] to a man from among them, [saying], \"Warn mankind and give good tidings to those who believe that they will have a [firm] precedence of honor with their Lord\"? [But] the disbelievers say, \"Indeed, this is an obvious magician.\"","ur":"کیا لوگوں کو تعجب ہوا کہ ہم نے ان ہی میں سے ایک مرد کو حکم بھیجا کہ لوگوں کو ڈر سنا دو۔ اور ایمان لانے والوں کو خوشخبری دے دو کہ ان کے پروردگار کے ہاں ان کا سچا درجہ ہے۔ (ایسے شخص کی نسبت) کافر کہتے ہیں کہ یہ صریح جادوگر ہے","hi":"क्या लोगों के लिए आश्चर्य की बात है कि हमने उनमें से एक व्यक्ति की ओर वह़्य (प्रकाशना) भेजी कि लोगों को डराए और उन लोगों को शुभ-सूचना दे, जो ईमान लाए हैं कि उनके लिए उनके पालनहार के पास उच्च स्थान है। काफ़िरों ने कहा : निःसंदेह यह तो खुला जादूगर है।"},{"a":3,"ar":"إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۖ يُدَبِّرُ ٱلْأَمْرَ ۖ مَا مِن شَفِيعٍ إِلَّا مِنۢ بَعْدِ إِذْنِهِۦ ۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ فَٱعْبُدُوهُ ۚ أَفَلَا تَذَكَّرُونَ","en":"Indeed, your Lord is Allāh, who created the heavens and the earth in six days and then established Himself above the Throne, arranging the matter [of His creation]. There is no intercessor except after His permission. That is Allāh, your Lord, so worship Him. Then will you not remember?","ur":"تمہارا پروردگار تو خدا ہی ہے جس نے آسمان اور زمین چھ دن میں بنائے پھر عرش (تخت شاہی) پر قائم ہوا وہی ہر ایک کا انتظام کرتا ہے۔ کوئی (اس کے پاس) اس کا اذن حاصل کیے بغیر کسی کی سفارش نہیں کرسکتا، یہی خدا تمہارا پروردگار ہے تو اسی کی عبادت کرو۔ بھلا تم غور کیوں نہیں کرتے","hi":"निःसंदेह तुम्हारा पालनहार अल्लाह ही है, जिसने आकाशों तथा धरती को छह दिनों में पैदा किया, फिर अर्श (सिंहासन) पर बुलंद हुआ। वह हर चीज़ की व्यवस्था चला रहा है। कोई सिफ़ारिश करने वाला नहीं परंतु उसकी अनुमति के बाद। वही अल्लाह तुम्हारा पालनहार है, अतः उसी की इबादत करो। क्या तुम उपदेश ग्रहण नहीं करतेॽ"},{"a":4,"ar":"إِلَيْهِ مَرْجِعُكُمْ جَمِيعًا ۖ وَعْدَ ٱللَّهِ حَقًّا ۚ إِنَّهُۥ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ لِيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ بِٱلْقِسْطِ ۚ وَٱلَّذِينَ كَفَرُوا۟ لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْفُرُونَ","en":"To Him is your return all together. [It is] the promise of Allāh [which is] truth. Indeed, He begins the [process of] creation and then repeats it that He may reward those who have believed and done righteous deeds, in justice. But those who disbelieved will have a drink of scalding water and a painful punishment for what they used to deny.","ur":"اسی کے پاس تم سب کو لوٹ کر جانا ہے۔ خدا کا وعدہ سچا ہے۔ وہی خلقت کو پہلی بار پیدا کرتا ہے۔ پھر وہی اس کو دوبارہ پیدا کرے گا تاکہ ایمان والوں اور نیک کام کرنے والوں کو انصاف کے ساتھ بدلہ دے۔ اور جو کافر ہیں ان کے لیے پینے کو نہایت گرم پانی اور درد دینے والا عذاب ہوگا کیوں کہ (خدا سے) انکار کرتے تھے","hi":"तुम सब को उसी की ओर लौटना है। यह अल्लाह का सच्चा वादा है। निःसंदेह वही रचना का आरंभ करता है, फिर उसे दोबारा पैदा करेगा, ताकि उन लोगों को न्याय के साथ बदला दे, जो ईमान लाए और अच्छे कर्म किए। तथा जिन लोगों ने कुफ़्र किया, उनके लिए खौलते हुए जल का पेय और दर्दनाक यातना है, उसके बदले जो वे कुफ़्र किया करते थे।"},{"a":5,"ar":"هُوَ ٱلَّذِى جَعَلَ ٱلشَّمْسَ ضِيَآءً وَٱلْقَمَرَ نُورًا وَقَدَّرَهُۥ مَنَازِلَ لِتَعْلَمُوا۟ عَدَدَ ٱلسِّنِينَ وَٱلْحِسَابَ ۚ مَا خَلَقَ ٱللَّهُ ذَٰلِكَ إِلَّا بِٱلْحَقِّ ۚ يُفَصِّلُ ٱلْـَٔايَـٰتِ لِقَوْمٍ يَعْلَمُونَ","en":"It is He who made the sun a shining light and the moon a derived light and determined for it phases - that you may know the number of years and account [of time]. Allāh has not created this except in truth. He details the signs for a people who know.","ur":"وہی تو ہے جس نے سورج کو روشن اور چاند کو منور بنایا اور چاند کی منزلیں مقرر کیں تاکہ تم برسوں کا شمار اور (کاموں کا) حساب معلوم کرو۔ یہ (سب کچھ) خدا نے تدبیر سے پیدا کیا ہے۔ سمجھنے والوں کے لیے وہ اپنی آیاتیں کھول کھول کر بیان فرماتا ہے","hi":"वही है जिसने सूर्य को ज्योति तथा चाँद को प्रकाश बनाया और उस (चाँद) की मंज़िलें निर्धारित कीं, ताकि तुम वर्षों की गिनती तथा हिसाब जान सको। अल्लाह ने इन सब को सत्य के साथ बनाया है। वह उन लोगों के लिए निशानियों को खोलकर बयान करता है, जो जानते हैं।"},{"a":6,"ar":"إِنَّ فِى ٱخْتِلَـٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَمَا خَلَقَ ٱللَّهُ فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ لَـَٔايَـٰتٍ لِّقَوْمٍ يَتَّقُونَ","en":"Indeed, in the alternation of the night and the day and [in] what Allāh has created in the heavens and the earth are signs for a people who fear Allāh.","ur":"رات اور دن کے (ایک دوسرے کے پیچھے) آنے جانے میں اور جو چیزیں خدا نے آسمان اور زمین میں پیدا کی ہیں (سب میں) ڈرنے والوں کے لیے نشانیاں ہیں","hi":"निःसंदेह रात और दिन के एक-दूसरे के बाद आने में और उन चीज़ों में जो अल्लाह ने आकाशों तथा धरती में पैदा की हैं, निश्चय उन लोगों के लिए निशानियाँ हैं, जो अल्लाह का डर रखते हैं।"},{"a":7,"ar":"إِنَّ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا وَرَضُوا۟ بِٱلْحَيَوٰةِ ٱلدُّنْيَا وَٱطْمَأَنُّوا۟ بِهَا وَٱلَّذِينَ هُمْ عَنْ ءَايَـٰتِنَا غَـٰفِلُونَ","en":"Indeed, those who do not expect the meeting with Us and are satisfied with the life of this world and feel secure therein and those who are heedless of Our signs -","ur":"جن لوگوں کو ہم سے ملنے کی توقع نہیں اور دنیا کی زندگی سے خوش اور اسی پر مطئمن ہو بیٹھے اور ہماری نشانیوں سے غافل ہو رہے ہیں","hi":"निःसंदेह जो लोग हमसे मिलने की आशा नहीं रखते और वे सांसारिक जीवन से प्रसन्न हो गए तथा उसी से संतुष्ट हो गए और वे लोग जो हमारी निशानियों से असावधान हैं।"},{"a":8,"ar":"أُو۟لَـٰٓئِكَ مَأْوَىٰهُمُ ٱلنَّارُ بِمَا كَانُوا۟ يَكْسِبُونَ","en":"For those their refuge will be the Fire because of what they used to earn.","ur":"ان کا ٹھکانہ ان (اعمال) کے سبب جو وہ کرتے ہیں دوزخ ہے","hi":"यही लोग हैं जिनका ठिकाना जहन्नम है, उसके बदले जो वे कमाया करते थे।"},{"a":9,"ar":"إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ يَهْدِيهِمْ رَبُّهُم بِإِيمَـٰنِهِمْ ۖ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَـٰرُ فِى جَنَّـٰتِ ٱلنَّعِيمِ","en":"Indeed, those who have believed and done righteous deeds - their Lord will guide them because of their faith. Beneath them rivers will flow in the Gardens of Pleasure.","ur":"اور جو لوگ ایمان لائے اور نیک کام کرتے رہے ان کو پروردگار ان کے ایمان کی وجہ سے (ایسے محلوں کی) راہ دکھائے گا (کہ) ان کے نیچے نعمت کے باغوں میں نہریں بہہ رہی ہوں گی","hi":"निःसंदेह जो लोग ईमान लाए और अच्छे कर्म किए, उनका पालनहार उनके ईमान के कारण उनका मार्गदर्शन करेगा, उनके नीचे नेमत के बाग़ों में नहरें बहती होंगी।"},{"a":10,"ar":"دَعْوَىٰهُمْ فِيهَا سُبْحَـٰنَكَ ٱللَّهُمَّ وَتَحِيَّتُهُمْ فِيهَا سَلَـٰمٌ ۚ وَءَاخِرُ دَعْوَىٰهُمْ أَنِ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ","en":"Their call therein will be, \"Exalted are You, O Allāh,\" and their greeting therein will be, \"Peace.\" And the last of their call will be, \"Praise to Allāh, Lord of the worlds!\"","ur":"(جب وہ) ان میں (ان نعمتوں کو دیکھوں گے تو بےساختہ) کہیں گے سبحان الله۔ اور آپس میں ان کی دعا سلامٌ علیکم ہوگی اور ان کا آخری قول یہ (ہوگا) کہ خدائے رب العالمین کی حمد (اور اس کا شکر) ہے","hi":"उनमें उनकी प्रार्थना यह होगी : ''ऐ अल्लाह! तू पवित्र है।'' और उनमें उनका अभिवादन 'सलाम' होगा, और उनकी प्रार्थना का अंत यह होगा कि : ''सब प्रशंसा अल्लाह के लिए है, जो सारे संसारों का पालनहार है।''"},{"a":11,"ar":"۞ وَلَوْ يُعَجِّلُ ٱللَّهُ لِلنَّاسِ ٱلشَّرَّ ٱسْتِعْجَالَهُم بِٱلْخَيْرِ لَقُضِىَ إِلَيْهِمْ أَجَلُهُمْ ۖ فَنَذَرُ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا فِى طُغْيَـٰنِهِمْ يَعْمَهُونَ","en":"And if Allāh was to hasten for the people the evil [they invoke] as He hastens for them the good, their term would have been ended for them. But We leave the ones who do not expect the meeting with Us, in their transgression, wandering blindly.","ur":"اور اگر خدا لوگوں کی برائی میں جلدی کرتا جس طرح وہ طلب خیر میں جلدی کرتے ہیں۔ تو ان کی (عمر کی) میعاد پوری ہوچکی ہوتی سو جن لوگوں کو ہم سے ملنے کی توقع نہیں انہیں ہم چھوڑے رکھتے ہیں کہ اپنی سرکشی میں بہکتے رہیں","hi":"और अगर अल्लाह लोगों को बुराई जल्दी दे दे, उन्हें बहुत जल्दी भलाई प्रदान करने की तरह, तो निश्चय उनकी ओर उनकी अवधि पूरी कर दी जाए। (किंतु) हम उन लोगों को जो हमसे मिलने की आशा नहीं रखते, उनकी सरकशी ही में भटकता हुआ छोड़ देते हैं।"},{"a":12,"ar":"وَإِذَا مَسَّ ٱلْإِنسَـٰنَ ٱلضُّرُّ دَعَانَا لِجَنۢبِهِۦٓ أَوْ قَاعِدًا أَوْ قَآئِمًا فَلَمَّا كَشَفْنَا عَنْهُ ضُرَّهُۥ مَرَّ كَأَن لَّمْ يَدْعُنَآ إِلَىٰ ضُرٍّ مَّسَّهُۥ ۚ كَذَٰلِكَ زُيِّنَ لِلْمُسْرِفِينَ مَا كَانُوا۟ يَعْمَلُونَ","en":"And when affliction touches man, he calls upon Us, whether lying on his side or sitting or standing; but when We remove from him his affliction, he continues [in disobedience] as if he had never called upon Us to [remove] an affliction that touched him. Thus is made pleasing to the transgressors that which they have been doing.","ur":"اور جب انسان کو تکلیف پہنچتی ہے تو لیٹا اور بیٹھا اور کھڑا (ہر حال میں) ہمیں پکارتا ہے۔ پھر جب ہم اس تکلیف کو اس سے دور کر دیتے ہیں تو (بےلحاظ ہو جاتا ہے اور) اس طرح گزر جاتا ہے گویا کسی تکلیف پہنچنے پر ہمیں کبھی پکارا ہی نہ تھا۔ اسی طرح حد سے نکل جانے والوں کو ان کے اعمال آراستہ کرکے دکھائے گئے ہیں","hi":"और जब मनुष्य को कोई दुःख पहुँचता है, तो अपने पहलू पर, या बैठा हुआ या खड़ा हुआ हमें पुकारता है। फिर जब हम उससे उसका दुःख दूर कर देते हैं, तो ऐसे चल देता है, जैसे उसने हमें किसी दुःख के पहुँचने पर पुकारा ही नहीं। इसी प्रकार सीमा से आगे बढ़ने वालों के लिए शोभित कर दिया गया, जो वे किया करते थे।"},{"a":13,"ar":"وَلَقَدْ أَهْلَكْنَا ٱلْقُرُونَ مِن قَبْلِكُمْ لَمَّا ظَلَمُوا۟ ۙ وَجَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَـٰتِ وَمَا كَانُوا۟ لِيُؤْمِنُوا۟ ۚ كَذَٰلِكَ نَجْزِى ٱلْقَوْمَ ٱلْمُجْرِمِينَ","en":"And We had already destroyed generations before you when they wronged, and their messengers had come to them with clear proofs, but they were not to believe. Thus do We recompense the criminal people.","ur":"اور تم سے پہلے ہم کئی امتوں کو جب انہوں نے ظلم کا راستہ اختیار کیا ہلاک کرچکے ہیں۔ اور ان کے پاس پیغمبر کھلی نشانیاں لے کر آئے مگر وہ ایسے نہ تھے کہ ایمان لاتے۔ ہم گنہگار لوگوں کو اسی طرح بدلہ دیا کرتے ہیں","hi":"और निःसंदेह हमने तुमसे पहले बहुत-से समुदायों को विनष्ट कर दिया, जब उन्होंने अत्याचार किया। हालाँकि उनके रसूल उनके पास खुली निशानियाँ लेकर आए थे, परंतु वे ऐसे नहीं थे कि ईमान लाते। इसी प्रकार हम अपराधी लोगों को बदला दिया करते हैं।"},{"a":14,"ar":"ثُمَّ جَعَلْنَـٰكُمْ خَلَـٰٓئِفَ فِى ٱلْأَرْضِ مِنۢ بَعْدِهِمْ لِنَنظُرَ كَيْفَ تَعْمَلُونَ","en":"Then We made you successors in the land after them so that We may observe how you will do.","ur":"پھر ہم نے ان کے بعد تم لوگوں کو ملک میں خلیفہ بنایا تاکہ دیکھیں تم کیسے کام کرتے ہو","hi":"फिर उनके बद हमने तुम्हें धरती में उत्तराधिकारी बनाया, ताकि हम देखें कि तुम कैसे कार्य करते हो?"},{"a":15,"ar":"وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَاتُنَا بَيِّنَـٰتٍ ۙ قَالَ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا ٱئْتِ بِقُرْءَانٍ غَيْرِ هَـٰذَآ أَوْ بَدِّلْهُ ۚ قُلْ مَا يَكُونُ لِىٓ أَنْ أُبَدِّلَهُۥ مِن تِلْقَآئِ نَفْسِىٓ ۖ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ ۖ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ","en":"And when Our verses are recited to them as clear evidences, those who do not expect the meeting with Us say, \"Bring us a Qur’ān other than this or change it.\" Say, [O Muḥammad], \"It is not for me to change it on my own accord. I only follow what is revealed to me. Indeed I fear, if I should disobey my Lord, the punishment of a tremendous Day.\"","ur":"اور جب ان کو ہماری آیتیں پڑھ کر سنائی جاتی ہیں تو جن لوگوں کو ہم سے ملنے کی امید نہیں وہ کہتے ہیں کہ (یا تو) اس کے سوا کوئی اور قرآن (بنا) لاؤ یا اس کو بدل دو۔ کہہ دو کہ مجھ کو اختیار نہیں ہے کہ اسے اپنی طرف سے بدل دو۔ میں تو اسی حکم کا تابع ہوں جو میری طرف آتا ہے۔ اگر میں اپنے پروردگار کی نافرمانی کروں تو مجھے بڑے (سخت) دن کے عذاب سے خوف آتا ہے","hi":"और जब उन्हें हमारी स्पष्ट आयतें सुनाई जाती हैं, तो जो लोग हमसे मिलने की आशा नहीं रखते, वे कहते हैं : \"इसके अलावा कोई और क़ुरआन ले आओ, या इसे बदल दो।\" कह दो : मेरे लिए यह संभव नहीं है कि मैं इसे अपनी ओर से बदल दूँ। मैं तो केवल उसी का पालन करता हूँ, जो मेरी ओर वह़्य की जाती है। निःसंदेह, यदि मैं अपने पालनहार की अवज्ञा करूँ, तो मुझे एक बड़े दिन की यातना का डर है।"},{"a":16,"ar":"قُل لَّوْ شَآءَ ٱللَّهُ مَا تَلَوْتُهُۥ عَلَيْكُمْ وَلَآ أَدْرَىٰكُم بِهِۦ ۖ فَقَدْ لَبِثْتُ فِيكُمْ عُمُرًا مِّن قَبْلِهِۦٓ ۚ أَفَلَا تَعْقِلُونَ","en":"Say, \"If Allāh had willed, I would not have recited it to you, nor would He have made it known to you, for I had remained among you a lifetime before it. Then will you not reason?\"","ur":"(یہ بھی) کہہ دو کہ اگر خدا چاہتا تو (نہ تو) میں ہی یہ (کتاب) تم کو پڑھ کر سناتا اور نہ وہی تمہیں اس سے واقف کرتا۔ میں اس سے پہلے تم میں ایک عمر رہا ہوں (اور کبھی ایک کلمہ بھی اس طرح کا نہیں کہا) بھلا تم سمجھتے نہیں","hi":"आप कह दें : यदि अल्लाह चाहता, तो मैं तुम्हें इसे पढ़कर न सुनाता और न वह तुम्हें इसकी ख़बर देता। फिर निःसंदेह मैं इससे पहले तुम्हारे बीच जीवन की एक अवधि व्यतीत कर चुका हूँ। तो क्या तुम नहीं समझतेॽ"},{"a":17,"ar":"فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَـٰتِهِۦٓ ۚ إِنَّهُۥ لَا يُفْلِحُ ٱلْمُجْرِمُونَ","en":"So who is more unjust than he who invents a lie about Allāh or denies His signs? Indeed, the criminals will not succeed.","ur":"تو اس سے بڑھ کر ظالم کون جو خدا پر جھوٹ افترا کرے اور اس کی آیتوں کو جھٹلائے۔ بےشک گنہگار فلاح نہیں پائیں گے","hi":"फिर उससे बढ़कर अत्याचारी कौन होगा, जो अल्लाह पर झूठा आरोप लगाए अथवा उसकी आयतों को झुठलाएॽ निःसंदेह अपराधी लोग सफल नहीं होते।"},{"a":18,"ar":"وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَيَقُولُونَ هَـٰٓؤُلَآءِ شُفَعَـٰٓؤُنَا عِندَ ٱللَّهِ ۚ قُلْ أَتُنَبِّـُٔونَ ٱللَّهَ بِمَا لَا يَعْلَمُ فِى ٱلسَّمَـٰوَٰتِ وَلَا فِى ٱلْأَرْضِ ۚ سُبْحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا يُشْرِكُونَ","en":"And they worship other than Allāh that which neither harms them nor benefits them, and they say, \"These are our intercessors with Allāh.\" Say, \"Do you inform Allāh of something He does not know in the heavens or on the earth?\" Exalted is He and high above what they associate with Him.","ur":"اور یہ (لوگ) خدا کے سوا ایسی چیزوں کی پرستش کرتے ہیں جو نہ ان کا کچھ بگاڑ ہی سکتی ہیں اور نہ کچھ بھلا ہی کر سکتی ہیں اور کہتے ہیں کہ یہ خدا کے پاس ہماری سفارش کرنے والے ہیں۔ کہہ دو کہ کیا تم خدا کو ایسی چیز بتاتے ہو جس کا وجود اسے نہ آسمانوں میں معلوم ہوتا ہے اور نہ زمین میں۔ وہ پاک ہے اور (اس کی شان) ان کے شرک کرنے سے بہت بلند ہے","hi":"और वे लोग अल्लाह को छोड़कर उनको पूजते हैं, जो न उन्हें कोई हानि पहुँचाते हैं और न उन्हें कोई लाभ पहुँचाते हैं और कहते हैं कि ये लोग अल्लाह के यहाँ हमारे सिफ़ारिशी हैं। आप कह दें : क्या तुम अल्लाह को ऐसी बात की सूचना दे रहे हो, जिसे वह न आकाशों में जानता है और न धरती में? वह पवित्र है और उससे बहुत ऊँचा है, जिसे वे साझीदार ठहराते हैं।"},{"a":19,"ar":"وَمَا كَانَ ٱلنَّاسُ إِلَّآ أُمَّةً وَٰحِدَةً فَٱخْتَلَفُوا۟ ۚ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ فِيمَا فِيهِ يَخْتَلِفُونَ","en":"And mankind was not but one community [united in religion], but [then] they differed. And if not for a word that preceded from your Lord, it would have been judged between them [immediately] concerning that over which they differ.","ur":"اور (سب) لوگ (پہلے) ایک ہی اُمت (یعنی ایک ہی ملت پر) تھے۔ پھر جدا جدا ہوگئے۔ اور اگر ایک بات جو تمہارے پروردگار کی طرف سے پہلے ہوچکی ہے نہ ہوتی تو جن باتوں میں وہ اختلاف کرتے ہیں ان میں فیصلہ کر دیا جاتا","hi":"तथा लोग एक ही समुदाय थे, फिर वे अलग-अलग हो गए और यदि वह बात न होती जो तुम्हारे पालनहार की ओर से पहले ही निश्चित हो चुकी, तो उनके बीच उसके बारे में अवश्य फ़ैसला कर दिया जाता, जिसमें वे विभेद कर रहे हैं।"},{"a":20,"ar":"وَيَقُولُونَ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦ ۖ فَقُلْ إِنَّمَا ٱلْغَيْبُ لِلَّهِ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ","en":"And they say, \"Why is a sign not sent down to him from his Lord?\" So say, \"The unseen is only for Allāh [to administer], so wait; indeed, I am with you among those who wait.\"","ur":"اور کہتے ہیں کہ اس پر اس کے پروردگار کی طرف سے کوئی نشانی کیوں نازل نہیں ہوئی۔ کہہ دو کہ غیب (کا علم) تو خدا کو ہے سو تم انتظار کرو۔ میں بھی تمہارے ساتھ انتظار کرتا ہوں","hi":"और वे कहते हैं कि उसपर उसके पालनहार की ओर से कोई निशानी क्यों नहीं उतारी गईॽ आप कह दें : परोक्ष (का ज्ञान) तो केवल अल्लाह के पास है। अतः तुम प्रतीक्षा करो, मैं भी तुम्हारे साथ प्रतीक्षा करने वालों में से हूँ।"},{"a":21,"ar":"وَإِذَآ أَذَقْنَا ٱلنَّاسَ رَحْمَةً مِّنۢ بَعْدِ ضَرَّآءَ مَسَّتْهُمْ إِذَا لَهُم مَّكْرٌ فِىٓ ءَايَاتِنَا ۚ قُلِ ٱللَّهُ أَسْرَعُ مَكْرًا ۚ إِنَّ رُسُلَنَا يَكْتُبُونَ مَا تَمْكُرُونَ","en":"And when We give the people a taste of mercy after adversity has touched them, at once they conspire against Our verses. Say, \"Allāh is swifter in strategy.\" Indeed, Our messengers [i.e., angels] record that which you conspire.","ur":"اور جب ہم لوگوں کو تکلیف پہنچنے کے بعد (اپنی) رحمت (سے آسائش) کا مزہ چکھاتے ہیں تو وہ ہماری آیتوں میں حیلے کرنے لگتے ہیں۔ کہہ دو کہ خدا بہت جلد حیلہ کرنے والا ہے۔ اور جو حیلے تم کرتے ہو ہمارے فرشتے ان کو لکھتے جاتے ہیں","hi":"और जब हम लोगों को उनके किसी तकलीफ़ में पड़ने के बाद कोई दया चखाते हैं, तो अचानक उनके लिए हमारी आयतों के बारे में कोई न कोई चाल होती है। कह दें कि अल्लाह अधिक तेज़ उपाय करने वाला है। निःसंदेह हमारे भेजे हुए (फ़रिश्ते) लिख रहे हैं, जो तुम चाल चलते हो।"},{"a":22,"ar":"هُوَ ٱلَّذِى يُسَيِّرُكُمْ فِى ٱلْبَرِّ وَٱلْبَحْرِ ۖ حَتَّىٰٓ إِذَا كُنتُمْ فِى ٱلْفُلْكِ وَجَرَيْنَ بِهِم بِرِيحٍ طَيِّبَةٍ وَفَرِحُوا۟ بِهَا جَآءَتْهَا رِيحٌ عَاصِفٌ وَجَآءَهُمُ ٱلْمَوْجُ مِن كُلِّ مَكَانٍ وَظَنُّوٓا۟ أَنَّهُمْ أُحِيطَ بِهِمْ ۙ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ لَئِنْ أَنجَيْتَنَا مِنْ هَـٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّـٰكِرِينَ","en":"It is He who enables you to travel on land and sea until, when you are in ships and they sail with them by a good wind and they rejoice therein, there comes a storm wind and the waves come upon them from every place and they expect to be engulfed, they supplicate Allāh, sincere to Him in religion, \"If You should save us from this, we will surely be among the thankful.\"","ur":"وہی تو ہے جو تم کو جنگل اور دریا میں چلنے پھرنے اور سیر کرنے کی توفیق دیتا ہے۔ یہاں تک کہ جب تم کشتیوں میں (سوار) ہوتے اور کشتیاں پاکیزہ ہوا (کے نرم نرم جھونکوں) سے سواروں کو لے کر چلنے لگتی ہیں اور وہ ان سے خوش ہوتے ہیں تو ناگہاں زناٹے کی ہوا چل پڑتی ہے اور لہریں ہر طرف سے ان پر (جوش مارتی ہوئی) آنے لگتی ہیں اور وہ خیال کرتے ہیں کہ (اب تو) لہروں میں گھر گئے تو اس وقت خالص خدا ہی کی عبادت کرکے اس سے دعا مانگنے لگتے ہیں کہ (اے خدا) اگر تو ہم کو اس سے نجات بخشے تو ہم (تیرے) بہت ہی شکر گزار ہوں","hi":"वही है जो तुम्हें जल और थल में चलाता है, यहाँ तक कि जब तुम नावों में होते हो और वे उन्हें लेकर अच्छी (अनुकूल) हवा के सहारे चल पड़ती हैं और वे उससे प्रसन्न हो उठते हैं, कि अचानक एक तेज़ हवा उन (नावों) पर आती है और उनपर प्रत्येक स्थान से लहरें आ जाती हैं और वे समझते हैं कि निःसंदेह उन्हें घेर लिया गया है, तो वे अल्लाह को इस तरह पुकारते हैं कि उसके लिए हर इबादत को विशुद्ध करने वाले होते हैं, निश्चय अगर तूने हमें उससे नजात दे दी, तो हम अवश्य ही शुक्रगुज़ारों में से होंगे।"},{"a":23,"ar":"فَلَمَّآ أَنجَىٰهُمْ إِذَا هُمْ يَبْغُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ ۗ يَـٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَا بَغْيُكُمْ عَلَىٰٓ أَنفُسِكُم ۖ مَّتَـٰعَ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ ثُمَّ إِلَيْنَا مَرْجِعُكُمْ فَنُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ","en":"But when He saves them, at once they commit injustice upon the earth without right. O mankind, your injustice is only against yourselves, [being merely] the enjoyment of worldly life. Then to Us is your return, and We will inform you of what you used to do.","ur":"لیکن جب وہ ان کو نجات دے دیتا ہے تو ملک میں ناحق شرارت کرنے لگتے ہیں۔ لوگو! تمہاری شرارت کا وبال تمہاری ہی جانوں پر ہوگا تم دنیا کی زندگی کے فائدے اُٹھا لو۔ پھر تم کو ہمارے پاس لوٹ کر آنا ہے۔ اس وقت ہم تم کو بتائیں گے جو کچھ تم کیا کرتے تھے","hi":"फिर जब वह उन्हें बचा लेता है, तो वे अचानक धरती में नाहक़ सरकशी करने लगते हैं। ऐ लोगो! तुम्हारी सरकशी, तुम्हारे अपने ही विरुद्ध है। ये सांसारिक जीवन के कुछ लाभ हैं। फिर तुम्हें हमारी ही ओर लौटकर आना है। तब हम तुम्हें बताएँगे जो कुछ तुम किया करते थे।"},{"a":24,"ar":"إِنَّمَا مَثَلُ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَآءٍ أَنزَلْنَـٰهُ مِنَ ٱلسَّمَآءِ فَٱخْتَلَطَ بِهِۦ نَبَاتُ ٱلْأَرْضِ مِمَّا يَأْكُلُ ٱلنَّاسُ وَٱلْأَنْعَـٰمُ حَتَّىٰٓ إِذَآ أَخَذَتِ ٱلْأَرْضُ زُخْرُفَهَا وَٱزَّيَّنَتْ وَظَنَّ أَهْلُهَآ أَنَّهُمْ قَـٰدِرُونَ عَلَيْهَآ أَتَىٰهَآ أَمْرُنَا لَيْلًا أَوْ نَهَارًا فَجَعَلْنَـٰهَا حَصِيدًا كَأَن لَّمْ تَغْنَ بِٱلْأَمْسِ ۚ كَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَـٰتِ لِقَوْمٍ يَتَفَكَّرُونَ","en":"The example of [this] worldly life is but like rain which We have sent down from the sky that the plants of the earth absorb - [those] from which men and livestock eat - until, when the earth has taken on its adornment and is beautified and its people suppose that they have capability over it, there comes to it Our command by night or by day, and We make it as a harvest, as if it had not flourished yesterday. Thus do We explain in detail the signs for a people who give thought.","ur":"دنیا کی زندگی کی مثال مینھہ کی سی ہے کہ ہم نے اس کو آسمان سے برسایا۔ پھر اس کے ساتھ سبزہ جسے آدمی اور جانور کھاتے ہیں مل کر نکلا یہاں تک کہ زمین سبزے سے خوشنما اور آراستہ ہوگئی اور زمین والوں نے خیال کیا کہ وہ اس پر پوری دسترس رکھتے ہیں ناگہاں رات کو یا دن کو ہمارا حکم (عذاب) آپہنچا تو ہم نے اس کو کاٹ (کر ایسا کر) ڈالا کہ گویا کل وہاں کچھ تھا ہی نہیں۔ جو لوگ غور کرنے والے ہیں۔ ان کے لیے ہم (اپنی قدرت کی) نشانیاں اسی طرح کھول کھول کر بیان کرتے ہیں","hi":"सांसारिक जीवन की मिसाल तो बस उस पानी जैसी है, जिसे हमने आकाश से बरसाया, तो उसके साथ धरती से उगने वाले पौधे ख़ूब मिल गए, जिन्हें इनसान और जानवर खाते हैं, यहाँ तक कि जब धरती ने अपनी शोभा पूरी कर ली और खूब ससज्जित हो गई और उसके मालिकों ने समझ लिया कि निःसंदेह वे उसपर सक्षम हैं, तो रात या दिन में उसपर हमारा आदेश आ गया, तो हमने उसे कटी हुई कर दिया, जैसे वह कल थी ही नहीं। इसी प्रकार हम उन लोगों के लिए आयतें खोलकर बयान करते हैं, जो मनन-चिंतन करते हैं।"},{"a":25,"ar":"وَٱللَّهُ يَدْعُوٓا۟ إِلَىٰ دَارِ ٱلسَّلَـٰمِ وَيَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ","en":"And Allāh invites to the Home of Peace [i.e., Paradise] and guides whom He wills to a straight path.","ur":"اور خدا سلامتی کے گھر کی طرف بلاتا ہے۔ اور جس کو چاہتا ہے سیدھا راستہ دکھاتا ہے","hi":"और अल्लाह शांति के घर की ओर बुलाता है और जिसे चाहता है सीधा मार्ग दिखा देता है।"},{"a":26,"ar":"۞ لِّلَّذِينَ أَحْسَنُوا۟ ٱلْحُسْنَىٰ وَزِيَادَةٌ ۖ وَلَا يَرْهَقُ وُجُوهَهُمْ قَتَرٌ وَلَا ذِلَّةٌ ۚ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَنَّةِ ۖ هُمْ فِيهَا خَـٰلِدُونَ","en":"For them who have done good is the best [reward] - and extra. No darkness will cover their faces, nor humiliation. Those are companions of Paradise; they will abide therein eternally.","ur":"جن لوگوں نے نیکو کاری کی ان کے لیے بھلائی ہے اور (مزید برآں) اور بھی اور ان کے مونہوں پر نہ تو سیاہی چھائے گی اور نہ رسوائی۔ یہی جنتی ہیں کہ اس میں ہمیشہ رہیں گے","hi":"जिन लोगों ने अच्छे कर्म किए, उन्हीं के लिए सबसे अच्छा बदला और कुछ अधिक है और उनके चेहरों पर न कोई कलौंस छाएगी और न ज़िल्लत। यही लोग जन्नत वाले हैं, वे उसमें हमेशा रहने वाले हैं।"},{"a":27,"ar":"وَٱلَّذِينَ كَسَبُوا۟ ٱلسَّيِّـَٔاتِ جَزَآءُ سَيِّئَةٍۭ بِمِثْلِهَا وَتَرْهَقُهُمْ ذِلَّةٌ ۖ مَّا لَهُم مِّنَ ٱللَّهِ مِنْ عَاصِمٍ ۖ كَأَنَّمَآ أُغْشِيَتْ وُجُوهُهُمْ قِطَعًا مِّنَ ٱلَّيْلِ مُظْلِمًا ۚ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ","en":"But they who have earned [blame for] evil doings - the recompense of an evil deed is its equivalent, and humiliation will cover them. They will have from Allāh no protector. It will be as if their faces are covered with pieces of the night - so dark [are they]. Those are the companions of the Fire; they will abide therein eternally.","ur":"اور جنہوں نے برے کام کئے تو برائی کا بدلہ ویسا ہی ہوگا۔ اور ان کے مونہوں پر ذلت چھا جائے گی۔ اور کوئی ان کو خدا سے بچانے والا نہ ہوگا۔ ان کے مونہوں (کی سیاہی کا یہ عالم ہوگا کہ ان) پر گویا اندھیری رات کے ٹکڑے اُڑھا دیئے گئے ہیں۔ یہی دوزخی ہیں کہ ہمیشہ اس میں رہیں گے","hi":"और जिन लोगों ने बुराइयाँ कमाईं, तो किसी भी बुराई का बदला उसी के समान मिलेगा और उनपर अपमान छाया होगा। उन्हें अल्लाह से बचाने वाला कोई न होगा। मानो कि उनके चेहरों पर अँधेरी रात के बहुत-से टुकड़े ओढ़ा दिए गए हों। यही लोग जहन्नम वाले हैं। वे उसमें हमेशा रहने वाले हैं।"},{"a":28,"ar":"وَيَوْمَ نَحْشُرُهُمْ جَمِيعًا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوا۟ مَكَانَكُمْ أَنتُمْ وَشُرَكَآؤُكُمْ ۚ فَزَيَّلْنَا بَيْنَهُمْ ۖ وَقَالَ شُرَكَآؤُهُم مَّا كُنتُمْ إِيَّانَا تَعْبُدُونَ","en":"And [mention, O Muḥammad], the Day We will gather them all together - then We will say to those who associated others with Allāh, \"[Remain in] your place, you and your 'partners.'\" Then We will separate them, and their \"partners\" will say, \"You did not used to worship us,","ur":"اور جس دن ہم ان سب کو جمع کریں گے پھر مشرکوں سے کہیں گے کہ تم اور تمہارے شریک اپنی اپنی جگہ ٹھہرے رہو۔ تو ہم ان میں تفرقہ ڈال دیں گے اور ان کے شریک (ان سے) کہیں گے کہ تم ہم کو نہیں پوجا کرتے تھے","hi":"और जिस दिन हम उन सबको एकत्र करेंगे, फिर हम उन लोगों से, जिन्होंने शिर्क किया, कहेंगे : तुम अपने साझीदारों समेत अपनी जगह ठहरे रहो, फिर हम उनके बीच अलगाव कर देंगे और उनके साझीदार कहेंगे कि तुम हमारी इबादत तो नहीं किया करते थे।"},{"a":29,"ar":"فَكَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنَنَا وَبَيْنَكُمْ إِن كُنَّا عَنْ عِبَادَتِكُمْ لَغَـٰفِلِينَ","en":"And sufficient is Allāh as a witness between us and you that we were of your worship unaware.\"","ur":"ہمارے اور تمہارے درمیان خدا ہی گواہ کافی ہے۔ ہم تمہاری پرستش سے بالکل بےخبر تھے","hi":"अतः हमारे और तुम्हारे बीच अल्लाह ही गवाह काफ़ी है कि निःसंदेह हम तुम्हारी इबादत से निश्चय बेख़बर थे।"},{"a":30,"ar":"هُنَالِكَ تَبْلُوا۟ كُلُّ نَفْسٍ مَّآ أَسْلَفَتْ ۚ وَرُدُّوٓا۟ إِلَى ٱللَّهِ مَوْلَىٰهُمُ ٱلْحَقِّ ۖ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ","en":"There, [on that Day], every soul will be put to trial for what it did previously, and they will be returned to Allāh, their master, the Truth, and lost from them is whatever they used to invent.","ur":"وہاں ہر شخص (اپنے اعمال کی) جو اس نے آگے بھیجے ہوں گے آزمائش کرلے گا اور وہ اپنے سچے مالک کی طرف لوٹائے جائیں گے اور جو کچھ وہ بہتان باندھا کرتے تھے سب ان سے جاتا رہے گا","hi":"उस अवसर पर प्रत्येक व्यक्ति अपने पहले के किए हुए कामों को जाँच लेगा और वे अपने सच्चे मालिक अल्लाह की ओर लौटाए जाएँगे और वे जो कुछ झूठा आरोप लगाया करते थे, सब उनसे गुम हो जाएगा।"},{"a":31,"ar":"قُلْ مَن يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ أَمَّن يَمْلِكُ ٱلسَّمْعَ وَٱلْأَبْصَـٰرَ وَمَن يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَيُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ وَمَن يُدَبِّرُ ٱلْأَمْرَ ۚ فَسَيَقُولُونَ ٱللَّهُ ۚ فَقُلْ أَفَلَا تَتَّقُونَ","en":"Say, \"Who provides for you from the heaven and the earth? Or who controls hearing and sight and who brings the living out of the dead and brings the dead out of the living and who arranges [every] matter?\" They will say, \"Allāh,\" so say, \"Then will you not fear Him?\"","ur":"(ان سے) پوچھو کہ تم کو آسمان اور زمین میں رزق کون دیتا ہے یا (تمہارے) کانوں اور آنکھوں کا مالک کون ہے اور بےجان سے جاندار کون پیدا کرتا ہے اور دنیا کے کاموں کا انتظام کون کرتا ہے۔ جھٹ کہہ دیں گے کہ خدا۔ تو کہو کہ پھر تم (خدا سے) ڈرتے کیوں نہیں؟","hi":"कहो : वह कौन है जो तुम्हें आकाश और धरती से जीविका देता है? या फिर कान और आँख का मालिक कौन है? और कौन जीवित को मृत से निकालता और मृत को जीवित से निकालता है? और कौन है जो हर काम का प्रबंध करता है? तो वे ज़रूर कहेंगे : ''अल्लाह'', तो कहो : फिर क्या तुम डरते नहीं?"},{"a":32,"ar":"فَذَٰلِكُمُ ٱللَّهُ رَبُّكُمُ ٱلْحَقُّ ۖ فَمَاذَا بَعْدَ ٱلْحَقِّ إِلَّا ٱلضَّلَـٰلُ ۖ فَأَنَّىٰ تُصْرَفُونَ","en":"For that is Allāh, your Lord, the Truth. And what can be beyond truth except error? So how are you averted?","ur":"یہی خدا تو تمہارا پروردگار برحق ہے۔ اور حق بات کے ظاہر ہونے کے بعد گمراہی کے سوا ہے ہی کیا؟ تو تم کہاں پھرے جاتے ہو","hi":"तो वह अल्लाह ही तुम्हारा सच्चा पालनहार है, फिर सत्य के बाद पथभ्रष्टता के सिवा और क्या हैॽ फिर तुम कहाँ फेरे जाते हो?"},{"a":33,"ar":"كَذَٰلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ فَسَقُوٓا۟ أَنَّهُمْ لَا يُؤْمِنُونَ","en":"Thus the word [i.e., decree] of your Lord has come into effect upon those who defiantly disobeyed - that they will not believe.","ur":"اسی طرح خدا کا ارشاد ان نافرمانوں کے حق میں ثابت ہو کر رہا کہ یہ ایمان نہیں لائیں گے","hi":"इसी प्रकार आपके पालनहार की बात उन लोगों के बारे में सत्य सिद्ध हुई जिन्होंने अवज्ञा की थी कि वे ईमान नहीं लाएँगे।"},{"a":34,"ar":"قُلْ هَلْ مِن شُرَكَآئِكُم مَّن يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ ۚ قُلِ ٱللَّهُ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ ۖ فَأَنَّىٰ تُؤْفَكُونَ","en":"Say, \"Are there of your 'partners' any who begins creation and then repeats it?\" Say, \"Allāh begins creation and then repeats it, so how are you deluded?\"","ur":"(ان سے) پوچھو کہ بھلا تمھارے شریکوں میں سے کوئی ایسا ہے کہ مخلوق کو ابتداً پیدا کرے (اور) پھر اس کو دوبارہ بنائے؟ کہہ دو کہ خدا ہی پہلی بار پیدا کرتا ہے پھر وہی اس کو دوبارہ پیدا کرے گا تو تم کہاں اُکسے جارہے ہو","hi":"(आप उनसे) कह दें : क्या तुम्हारे साझीदारों में से कोई है, जो सृष्टि का आरंभ करता हो, फिर उसे दोबारा बनाता होॽ आप कह दें : अल्लाह ही सृष्टि का आरंभ करता है, फिर उसे दोबारा बनाता है, तो तुम कहाँ बहकाए जाते होॽ"},{"a":35,"ar":"قُلْ هَلْ مِن شُرَكَآئِكُم مَّن يَهْدِىٓ إِلَى ٱلْحَقِّ ۚ قُلِ ٱللَّهُ يَهْدِى لِلْحَقِّ ۗ أَفَمَن يَهْدِىٓ إِلَى ٱلْحَقِّ أَحَقُّ أَن يُتَّبَعَ أَمَّن لَّا يَهِدِّىٓ إِلَّآ أَن يُهْدَىٰ ۖ فَمَا لَكُمْ كَيْفَ تَحْكُمُونَ","en":"Say, \"Are there of your 'partners' any who guides to the truth?\" Say, \"Allāh guides to the truth. So is He who guides to the truth more worthy to be followed or he who guides not unless he is guided? Then what is [wrong] with you - how do you judge?\"","ur":"پوچھو کہ بھلا تمہارے شریکوں میں کون ایسا ہے کہ حق کا رستہ دکھائے۔ کہہ دو کہ خدا ہی حق کا رستہ دکھاتا ہے۔ بھلا جو حق کا رستہ دکھائے وہ اس قابل ہے کہ اُس کی پیروی کی جائے یا وہ کہ جب تک کوئی اسے رستہ نہ بتائے رستہ نہ پائے۔ تو تم کو کیا ہوا ہے کیسا انصاف کرتے ہو؟","hi":"आप कह दें कि क्या तुम्हारे साझीदारों में से कोई है, जो सत्य की ओर मार्गदर्शन करे? आप कह दें कि अल्लाह ही सत्य का मार्गदर्शन करता है। तो क्या जो सत्य की ओर मार्गदर्शन करे, वह अधिक हक़दार है कि उसका अनुसरण किया जाए, या वह जो स्वयं रास्ता नहीं पाता सिवाय इसके कि उसे रास्ता बताया जाए? फिर तुम्हें क्या है, तुम कैसे फ़ैसला करते होॽ"},{"a":36,"ar":"وَمَا يَتَّبِعُ أَكْثَرُهُمْ إِلَّا ظَنًّا ۚ إِنَّ ٱلظَّنَّ لَا يُغْنِى مِنَ ٱلْحَقِّ شَيْـًٔا ۚ إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا يَفْعَلُونَ","en":"And most of them follow not except assumption. Indeed, assumption avails not against the truth at all. Indeed, Allāh is Knowing of what they do.","ur":"اور ان میں سے اکثر صرف ظن کی پیروی کرتے ہیں۔ اور کچھ شک نہیں کہ ظن حق کے مقابلے میں کچھ بھی کارآمد نہیں ہوسکتا۔ بےشک خدا تمہارے (سب) افعال سے واقف ہے","hi":"और उनमें से अधिकांश लोग केवल अनुमान का पालन करते हैं। निश्चित रूप से अनुमान सत्य की तुलना में किसी काम का नहीं है। निःसंदेह अल्लाह उसे भली-भाँति जानने वाला है, जो कुछ वे कर रहे हैं।"},{"a":37,"ar":"وَمَا كَانَ هَـٰذَا ٱلْقُرْءَانُ أَن يُفْتَرَىٰ مِن دُونِ ٱللَّهِ وَلَـٰكِن تَصْدِيقَ ٱلَّذِى بَيْنَ يَدَيْهِ وَتَفْصِيلَ ٱلْكِتَـٰبِ لَا رَيْبَ فِيهِ مِن رَّبِّ ٱلْعَـٰلَمِينَ","en":"And it was not [possible] for this Qur’ān to be produced by other than Allāh, but [it is] a confirmation of what was before it and a detailed explanation of the [former] Scripture, about which there is no doubt, from the Lord of the worlds.","ur":"اور یہ قرآن ایسا نہیں کہ خدا کے سوا کوئی اس کو اپنی طرف سے بنا لائے۔ ہاں (ہاں یہ خدا کا کلام ہے) جو (کتابیں) اس سے پہلے (کی) ہیں۔ ان کی تصدیق کرتا ہے اور ان ہی کتابوں کی (اس میں) تفصیل ہے اس میں کچھ شک نہیں (کہ) یہ رب العالمین کی طرف سے (نازل ہوا) ہے","hi":"और यह क़ुरआन ऐसा नहीं है कि अल्लाह के अलावा किसी और द्वारा घड़ लिया जाए, बल्कि यह उसकी पुष्टि करता है, जो इससे पहले है और किताब का विवरण (अर्थात् हलाल एवं हराम तथा धर्म के नियमों की व्याख्या) है। इसमें कोई संदेह नहीं कि यह सारे संसारों के पालनहार की ओर से है।"},{"a":38,"ar":"أَمْ يَقُولُونَ ٱفْتَرَىٰهُ ۖ قُلْ فَأْتُوا۟ بِسُورَةٍ مِّثْلِهِۦ وَٱدْعُوا۟ مَنِ ٱسْتَطَعْتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَـٰدِقِينَ","en":"Or do they say [about the Prophet (ﷺ)], \"He invented it?\" Say, \"Then bring forth a sūrah like it and call upon [for assistance] whomever you can besides Allāh, if you should be truthful.\"","ur":"کیا یہ لوگ کہتے ہیں کہ پیغمبر نے اس کو اپنی طرف سے بنا لیا ہے کہہ دو کہ اگر سچے ہو تو تم بھی اس طرح کی ایک سورت بنا لاؤ اور خدا کے سوا جن کو تم بلا سکو بلا بھی لو","hi":"क्या वे कहते हैं कि उसने इस (क़ुरआन) को स्वयं गढ़ लिया हैॽ आप कह दें : तो तुम इस जैसी एक सूरत ले आओ और अल्लाह के सिवा जिसे बुला सको बुला लो, यदि तुम सच्चे हो।"},{"a":39,"ar":"بَلْ كَذَّبُوا۟ بِمَا لَمْ يُحِيطُوا۟ بِعِلْمِهِۦ وَلَمَّا يَأْتِهِمْ تَأْوِيلُهُۥ ۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ ۖ فَٱنظُرْ كَيْفَ كَانَ عَـٰقِبَةُ ٱلظَّـٰلِمِينَ","en":"Rather, they have denied that which they encompass not in knowledge and whose interpretation has not yet come to them. Thus did those before them deny. Then observe how was the end of the wrongdoers.","ur":"حقیقت یہ ہے کہ جس چیز کے علم پر یہ قابو نہیں پاسکے اس کو (نادانی سے) جھٹلا دیا اور ابھی اس کی حقیقت ان پر کھلی ہی نہیں۔ اسی طرح جو لوگ ان سے پہلے تھے انہوں نے تکذیب کی تھی سو دیکھ لو ظالموں کا انجام کیسا ہوا","hi":"बल्कि उन्होंने उस चीज़ को झुठला दिया, जो उनके ज्ञान के घेरे में नहीं आया, हालाँकि उसका वास्तविक तथ्य अभी तक उनके पास नहीं आया था। इसी तरह उन लोगों ने झुठलाया जो इनसे पहले थे। तो देखो कि अत्याचारियों का परिणाम कैसा हुआ?"},{"a":40,"ar":"وَمِنْهُم مَّن يُؤْمِنُ بِهِۦ وَمِنْهُم مَّن لَّا يُؤْمِنُ بِهِۦ ۚ وَرَبُّكَ أَعْلَمُ بِٱلْمُفْسِدِينَ","en":"And of them are those who believe in it, and of them are those who do not believe in it. And your Lord is most knowing of the corrupters.","ur":"اور ان میں سے کچھ تو ایسے ہیں کہ اس پر ایمان لے آتے ہیں اور کچھ ایسے ہیں کہ ایمان نہیں لاتے۔ اور تمھارا پروردگار شریروں سے خوب واقف ہے","hi":"और उनमें से कुछ ऐसे हैं जो इस (क़ुरआन) पर ईमान लाते हैं और उनमें से कुछ ऐसे हैं जो इसपर ईमान नहीं लाते और आपका पालनहार बिगाड़ पैदा करने वालों को भली-भाँति जानने वाला है।"},{"a":41,"ar":"وَإِن كَذَّبُوكَ فَقُل لِّى عَمَلِى وَلَكُمْ عَمَلُكُمْ ۖ أَنتُم بَرِيٓـُٔونَ مِمَّآ أَعْمَلُ وَأَنَا۠ بَرِىٓءٌ مِّمَّا تَعْمَلُونَ","en":"And if they deny you, [O Muḥammad], then say, \"For me are my deeds, and for you are your deeds. You are disassociated from what I do, and I am disassociated from what you do.\"","ur":"اور اگر یہ تمہاری تکذیب کریں تو کہہ دو کہ مجھ کو میرے اعمال (کا بدلہ ملے گا) اور تم کو تمہارے اعمال (کا) تم میرے عملوں کا جواب دہ نہیں ہو اور میں تمہارے عملوں کا جوابدہ نہیں ہوں","hi":"और यदि वे आपको झुठलाएँ, तो आप कह दें कि मेरे लिए मेरा कर्म है और तुम्हारे लिए तुम्हारा कर्म। तुमपर उसका दोष नहीं, जो मैं करता हूँ और मुझपर उसका दोष नहीं, जो तुम करते हो।"},{"a":42,"ar":"وَمِنْهُم مَّن يَسْتَمِعُونَ إِلَيْكَ ۚ أَفَأَنتَ تُسْمِعُ ٱلصُّمَّ وَلَوْ كَانُوا۟ لَا يَعْقِلُونَ","en":"And among them are those who listen to you. But can you cause the deaf to hear [i.e., benefit from this hearing], although they will not use reason?","ur":"اور ان میں سے بعض ایسے ہیں کہ تمہاری طرف کان لگاتے ہیں تو کیا تم بہروں کو سناؤ گے اگرچہ کچھ بھی (سنتے) سمجھتے نہ ہوں","hi":"और उनमें से कुछ ऐसे हैं, जो आपकी ओर कान लगाते हैं। तो क्या आप बहरों को सुनाएँगे, अगरचे वे कुछ भी न समझते होंॽ"},{"a":43,"ar":"وَمِنْهُم مَّن يَنظُرُ إِلَيْكَ ۚ أَفَأَنتَ تَهْدِى ٱلْعُمْىَ وَلَوْ كَانُوا۟ لَا يُبْصِرُونَ","en":"And among them are those who look at you. But can you guide the blind although they will not [attempt to] see?","ur":"اور بعض ایسے ہیں کہ تمھاری طرف دیکھتے ہیں۔ تو کیا تم اندھوں کو راستہ دکھاؤ گے اگرچہ کچھ بھی دیکھتے (بھالتے) نہ ہوں","hi":"और उनमें से कुछ ऐसे हैं, जो आपकी ओर देखते हैं। तो क्या आप अंधों को मार्ग दिखाएँगे, यद्यपि वे न देखते होंॽ"},{"a":44,"ar":"إِنَّ ٱللَّهَ لَا يَظْلِمُ ٱلنَّاسَ شَيْـًٔا وَلَـٰكِنَّ ٱلنَّاسَ أَنفُسَهُمْ يَظْلِمُونَ","en":"Indeed, Allāh does not wrong the people at all, but it is the people who are wronging themselves.","ur":"خدا تو لوگوں پر کچھ ظلم نہیں کرتا لیکن لوگ ہی اپنے آپ پر ظلم کرتے ہیں","hi":"निःसंदेह अल्लाह लोगों पर कुछ भी अत्याचार नहीं करता, परंतु लोग स्वयं ही अपने ऊपर अत्याचार करते हैं।"},{"a":45,"ar":"وَيَوْمَ يَحْشُرُهُمْ كَأَن لَّمْ يَلْبَثُوٓا۟ إِلَّا سَاعَةً مِّنَ ٱلنَّهَارِ يَتَعَارَفُونَ بَيْنَهُمْ ۚ قَدْ خَسِرَ ٱلَّذِينَ كَذَّبُوا۟ بِلِقَآءِ ٱللَّهِ وَمَا كَانُوا۟ مُهْتَدِينَ","en":"And on the Day when He will gather them, [it will be] as if they had not remained [in the world] but an hour of the day, [and] they will know each other. Those will have lost who denied the meeting with Allāh and were not guided.","ur":"اور جس دن خدا ان کو جمع کرے گا (تو وہ دنیا کی نسبت ایسا خیال کریں گے کہ) گویا (وہاں) گھڑی بھر دن سے زیادہ رہے ہی نہیں تھے (اور) آپس میں ایک دوسرے کو شناخت بھی کریں گے۔ جن لوگوں نے خدا کے روبرو حاضر ہونے کو جھٹلایا وہ خسارے میں پڑ گئے اور راہ یاب نہ ہوئے","hi":"और जिस दिन वह उन्हें इकट्ठा करेगा, (उन्हें लगेगा) मानो वे दिन की एक घड़ी भर ठहरे हों, वे एक-दूसरे को पहचानेंगे। निःसंदेह वे लोग घाटे में पड़ गए, जिन्होंने अल्लाह से मिलने को झुठलाया और वे मार्ग पाने वाले न हुए।"},{"a":46,"ar":"وَإِمَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا مَرْجِعُهُمْ ثُمَّ ٱللَّهُ شَهِيدٌ عَلَىٰ مَا يَفْعَلُونَ","en":"And whether We show you some of what We promise them, [O Muḥammad], or We take you in death, to Us is their return; then, [either way], Allāh is a witness concerning what they are doing.","ur":"اور اگر ہم کوئی عذاب جس کا ان لوگوں سے وعدہ کرتے ہیں تمہاری آنکھوں کے سامنے (نازل) کریں یا (اس وقت جب) تمہاری مدت حیات پوری کردیں تو ان کو ہمارے ہی پاس لوٹ کر آنا ہے پھر جو کچھ یہ کر رہے ہیں خدا اس کو دیکھ رہا ہے","hi":"और अगर कभी हम आपको उसका कुछ हिस्सा दिखा दें, जो हम उनसे वादा करते हैं, या आपको उठा ही लें, तो उनकी वापसी हमारी ही ओर है, फिर जो कुछ वे कर रहे हैं अल्लाह उसका गवाह है।"},{"a":47,"ar":"وَلِكُلِّ أُمَّةٍ رَّسُولٌ ۖ فَإِذَا جَآءَ رَسُولُهُمْ قُضِىَ بَيْنَهُم بِٱلْقِسْطِ وَهُمْ لَا يُظْلَمُونَ","en":"And for every nation is a messenger. So when their messenger comes, it will be judged between them in justice, and they will not be wronged.","ur":"اور ہر ایک اُمت کی طرف سے پیغمبر بھیجا گیا۔ جب ان کا پیغمبر آتا ہے تو اُن میں انصاف کے ساتھ فیصلہ کر دیا جاتا ہے اور ان پر کچھ ظلم نہیں کیا جاتا","hi":"और प्रत्येक समुदाय के लिए एक रसूल है। फिर जब उनका रसूल आ जाता है, तो उनके बीच न्याय के साथ फ़ैसला कर दिया जाता है और उनपर अत्याचार नहीं किया जाता।"},{"a":48,"ar":"وَيَقُولُونَ مَتَىٰ هَـٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَـٰدِقِينَ","en":"And they say, \"When is [the fulfillment of] this promise, if you should be truthful?\"","ur":"اور یہ کہتے ہیں کہ اگر تم سچے ہو تو (جس عذاب کا) یہ وعدہ (ہے وہ آئے گا) کب؟","hi":"और वे कहते हैं कि यह वादा कब पूरा होगा, यदि तुम सच्चे होॽ"},{"a":49,"ar":"قُل لَّآ أَمْلِكُ لِنَفْسِى ضَرًّا وَلَا نَفْعًا إِلَّا مَا شَآءَ ٱللَّهُ ۗ لِكُلِّ أُمَّةٍ أَجَلٌ ۚ إِذَا جَآءَ أَجَلُهُمْ فَلَا يَسْتَـْٔخِرُونَ سَاعَةً ۖ وَلَا يَسْتَقْدِمُونَ","en":"Say, \"I possess not for myself any harm or benefit except what Allāh should will. For every nation is a [specified] term. When their time has come, then they will not remain behind an hour, nor will they precede [it].\"","ur":"کہہ دو کہ میں اپنے نقصان اور فائدے کا بھی کچھ اختیار نہیں رکھتا۔ مگر جو خدا چاہے۔ ہر ایک امت کے لیے (موت کا) ایک وقت مقرر ہے۔ جب وہ وقت آجاتا ہے تو ایک گھڑی بھی دیر نہیں کرسکتے اور نہ جلدی کرسکتے ہیں","hi":"आप कह दें कि मैं अपने लिए किसी हानि या लाभ का मालिक नहीं हूँ, परंतु जो अल्लाह चाहे। प्रत्येक समुदाय का एक समय है। जब उनका समय आ जाता है, तो वे एक घड़ी न पीछे रहते हैं और न आगे बढ़ते हैं।"},{"a":50,"ar":"قُلْ أَرَءَيْتُمْ إِنْ أَتَىٰكُمْ عَذَابُهُۥ بَيَـٰتًا أَوْ نَهَارًا مَّاذَا يَسْتَعْجِلُ مِنْهُ ٱلْمُجْرِمُونَ","en":"Say, \"Have you considered: if His punishment should come to you by night or by day - for which [aspect] of it would the criminals be impatient?\"","ur":"کہہ دو کہ بھلا دیکھو تو اگر اس کا عذاب تم پر (ناگہاں) آجائے رات کو یا دن کو تو پھر گنہگار کس بات کی جلدی کریں گے","hi":"(ऐ नबी!) कह दें कि तुम बताओ, यदि उसकी यातना तुमपर रात को या दिन के समय आ जाए, तो अपराधी इसमें से कौन-सी चीज़ जल्दी माँग रहे हैं?"},{"a":51,"ar":"أَثُمَّ إِذَا مَا وَقَعَ ءَامَنتُم بِهِۦٓ ۚ ءَآلْـَٔـٰنَ وَقَدْ كُنتُم بِهِۦ تَسْتَعْجِلُونَ","en":"Then is it that when it has [actually] occurred you will believe in it? Now? And you were [once] for it impatient.","ur":"کیا جب وہ آ واقع ہوگا تب اس پر ایمان لاؤ گے (اس وقت کہا جائے گا کہ) اور اب (ایمان لائے؟) اس کے لیے تو تم جلدی مچایا کرتے تھے","hi":"क्या फिर जब वह (यातना) आ जाएगी, तो उसपर ईमान लाओगे? क्या अब! हालाँकि निश्चय तुम इसी के लिए जल्दी मचा रहे थे?"},{"a":52,"ar":"ثُمَّ قِيلَ لِلَّذِينَ ظَلَمُوا۟ ذُوقُوا۟ عَذَابَ ٱلْخُلْدِ هَلْ تُجْزَوْنَ إِلَّا بِمَا كُنتُمْ تَكْسِبُونَ","en":"Then it will be said to those who had wronged, \"Taste the punishment of eternity; are you being recompensed except for what you used to earn?\"","ur":"پھر ظالم لوگوں سے کہا جائے گا کہ عذاب دائمی کا مزہ چکھو۔ (اب) تم انہیں (اعمال) کا بدلہ پاؤ گے جو (دنیا میں) کرتے رہے","hi":"फिर अत्याचारियों से कहा जाएगा कि स्थायी यातना का मज़ा चखो। तुम्हें उसी का बदला दिया जाएगा, जो तुम कमाया करते थे।"},{"a":53,"ar":"۞ وَيَسْتَنۢبِـُٔونَكَ أَحَقٌّ هُوَ ۖ قُلْ إِى وَرَبِّىٓ إِنَّهُۥ لَحَقٌّ ۖ وَمَآ أَنتُم بِمُعْجِزِينَ","en":"And they ask information of you, [O Muḥammad], \"Is it true?\" Say, \"Yes, by my Lord. Indeed, it is truth; and you will not cause failure [to Allāh].\"","ur":"اور تم سے دریافت کرتے ہیں کہ آیا یہ سچ ہے۔ کہہ دو ہاں خدا کی قسم سچ ہے اور تم (بھاگ کر خدا کو) عاجز نہیں کرسکو گے","hi":"और वे आपसे पूछते हैं कि क्या यह बात सत्य ही है? आप कह दें : हाँ, मेरे पालनहार की क़सम! निःसंदेह यह अवश्य सत्य है और तुम अल्लाह को बिल्कुल भी विवश करने वाले नहीं हो।"},{"a":54,"ar":"وَلَوْ أَنَّ لِكُلِّ نَفْسٍ ظَلَمَتْ مَا فِى ٱلْأَرْضِ لَٱفْتَدَتْ بِهِۦ ۗ وَأَسَرُّوا۟ ٱلنَّدَامَةَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ ۖ وَقُضِىَ بَيْنَهُم بِٱلْقِسْطِ ۚ وَهُمْ لَا يُظْلَمُونَ","en":"And if each soul that wronged had everything on earth, it would offer it in ransom. And they will confide regret when they see the punishment; and they will be judged in justice, and they will not be wronged.","ur":"اور اگر ہر ایک نافرمان شخص کے پاس روئے زمین کی تمام چیزیں ہوں تو (عذاب سے بچنے کے) بدلے میں (سب) دے ڈالے اور جب وہ عذاب کو دیکھیں گے تو (پچھتائیں گے اور) ندامت کو چھپائیں گے۔ اور ان میں انصاف کے ساتھ فیصلہ کر دیا جائے گا اور (کسی طرح کا) ان پر ظلم نہیں ہوگا","hi":"यदि अपने आपपर अत्याचार करने वाले व्यक्ति के पास वह सब कुछ हो, जो धरती पर है, तो वह उसे अवश्य छुड़ौती के रूप में दे डाले। और जब वे यातना को देखेंगे, तो अपने पछतावे को छिपाएँगे। तथा उनके बीच न्याय के साथ फ़ैसला कर दिया जाएगा और उनपर कोई अत्याचार नहीं किया जाएगा।"},{"a":55,"ar":"أَلَآ إِنَّ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۗ أَلَآ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ","en":"Unquestionably, to Allāh belongs whatever is in the heavens and the earth. Unquestionably, the promise of Allāh is truth, but most of them do not know.","ur":"سن رکھو جو کچھ آسمانوں اور زمینوں میں ہے سب خدا ہی کا ہے۔ اور یہ بھی سن رکھو کہ خدا کا وعدہ سچا ہے لیکن اکثر لوگ نہیں جانتے","hi":"सुनो! आकाशों और धरती में जो कुछ है, अल्लाह ही का है। सुनो! निःसंदेह अल्लाह का वादा सच्चा है, लेकिन उनमें से अधिकतर लोग नहीं जानते।"},{"a":56,"ar":"هُوَ يُحْىِۦ وَيُمِيتُ وَإِلَيْهِ تُرْجَعُونَ","en":"He gives life and causes death, and to Him you will be returned.","ur":"وہی جان بخشتا اور (وہی) موت دیتا ہے اور تم لوگ اسی کی طرف لوٹ کر جاؤ گے","hi":"वही जीवन देता तथा मारता है और उसी की ओर तुम लौटाए जाओगे।"},{"a":57,"ar":"يَـٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَتْكُم مَّوْعِظَةٌ مِّن رَّبِّكُمْ وَشِفَآءٌ لِّمَا فِى ٱلصُّدُورِ وَهُدًى وَرَحْمَةٌ لِّلْمُؤْمِنِينَ","en":"O mankind, there has come to you instruction from your Lord and healing for what is in the breasts and guidance and mercy for the believers.","ur":"لوگو تمہارے پروردگار کی طرف سے نصیحت اور دلوں کی بیماریوں کی شفا۔ اور مومنوں کے لیے ہدایت اور رحمت آپہنچی ہے","hi":"ऐ लोगो! निःसंदेह तुम्हारे पास तुम्हारे पालनहार की ओर से बड़ी नसीहत और सीनों में जो कुछ (रोग) है उसके लिए पूर्णतया शिफ़ा और ईमान वालों के लिए सर्वथा हिदायत और रहमत आई है।"},{"a":58,"ar":"قُلْ بِفَضْلِ ٱللَّهِ وَبِرَحْمَتِهِۦ فَبِذَٰلِكَ فَلْيَفْرَحُوا۟ هُوَ خَيْرٌ مِّمَّا يَجْمَعُونَ","en":"Say, \"In the bounty of Allāh and in His mercy - in that let them rejoice; it is better than what they accumulate.\"","ur":"کہہ دو کہ (یہ کتاب) خدا کے فضل اور اس کی مہربانی سے (نازل ہوئی ہے) تو چاہیئے کہ لوگ اس سے خوش ہوں۔ یہ اس سے کہیں بہتر ہے جو وہ جمع کرتے ہیں","hi":"आप कह दें : (यह) अल्लाह के अनुग्रह और उसकी दया के कारण है। अतः उन्हें इसी पर प्रसन्न होना चाहिए। यह उससे उत्तम है, जो वे इकट्ठा कर रहे हैं।"},{"a":59,"ar":"قُلْ أَرَءَيْتُم مَّآ أَنزَلَ ٱللَّهُ لَكُم مِّن رِّزْقٍ فَجَعَلْتُم مِّنْهُ حَرَامًا وَحَلَـٰلًا قُلْ ءَآللَّهُ أَذِنَ لَكُمْ ۖ أَمْ عَلَى ٱللَّهِ تَفْتَرُونَ","en":"Say, \"Have you seen what Allāh has sent down to you of provision of which you have made [some] lawful and [some] unlawful?\" Say, \"Has Allāh permitted you [to do so], or do you invent [something] about Allāh?\"","ur":"کہو کہ بھلا دیکھو تو خدا نے تمھارے لئے جو رزق نازل فرمایا تو تم نے اس میں سے (بعض کو) حرام ٹھہرایا اور (بعض کو) حلال (ان سے) پوچھو کیا خدا نے تم کو اس کا حکم دیا ہے یا تم خدا پر افتراء کرتے ہو","hi":"(ऐ नबी!) कह दें : क्या तुमने देखा जो अल्लाह ने तुम्हारे लिए रोज़ी उतारी है, फिर तुमने उसमें से कुछ को हराम और कुछ को हलाल ठहरा लिया? (आप उनसे) पूछें : क्या अल्लाह ने तुम्हें (इसकी) अनुमति दी है या तुम अल्लाह पर झूठा आरोप लगा रहे होॽ"},{"a":60,"ar":"وَمَا ظَنُّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ يَوْمَ ٱلْقِيَـٰمَةِ ۗ إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ","en":"And what will be the supposition of those who invent falsehood about Allāh on the Day of Resurrection? Indeed, Allāh is the possessor of bounty for the people, but most of them are not grateful.","ur":"اور جو لوگ خدا پر افتراء کرتے ہیں وہ قیامت کے دن کی نسبت کیا خیال رکھتے ہیں؟ بےشک خدا لوگوں پر مہربان ہے لیکن اکثر لوگ شکر نہیں کرتے","hi":"और जो लोग अल्लाह पर झूठा आरोप लगा रहे हैं, उनका क़ियामत के दिन के बारे में क्या ख़याल हैॽ निःसंदेह अल्लाह तो लोगों पर बड़े अनुग्रह वाला है, परंतु उनमें से अक्सर शुक्र अदा नहीं करते।"},{"a":61,"ar":"وَمَا تَكُونُ فِى شَأْنٍ وَمَا تَتْلُوا۟ مِنْهُ مِن قُرْءَانٍ وَلَا تَعْمَلُونَ مِنْ عَمَلٍ إِلَّا كُنَّا عَلَيْكُمْ شُهُودًا إِذْ تُفِيضُونَ فِيهِ ۚ وَمَا يَعْزُبُ عَن رَّبِّكَ مِن مِّثْقَالِ ذَرَّةٍ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ وَلَآ أَصْغَرَ مِن ذَٰلِكَ وَلَآ أَكْبَرَ إِلَّا فِى كِتَـٰبٍ مُّبِينٍ","en":"And, [O Muḥammad], you are not [engaged] in any matter and do not recite any of the Qur’ān and you [people] do not do any deed except that We are witness over you when you are involved in it. And not absent from your Lord is any [part] of an atom's weight within the earth or within the heaven or [anything] smaller than that or greater but that it is in a clear register.","ur":"اور تم جس حال میں ہوتے ہو یا قرآن میں کچھ پڑھتے ہو یا تم لوگ کوئی (اور) کام کرتے ہو جب اس میں مصروف ہوتے ہو ہم تمہارے سامنے ہوتے ہیں اور تمہارے پروردگار سے ذرہ برابر بھی کوئی چیز پوشیدہ نہیں ہے نہ زمین میں نہ آسمان میں اور نہ کوئی چیز اس سے چھوٹی ہے یا بڑی مگر کتاب روشن میں (لکھی ہوئی) ہے","hi":"(ऐ नबी!) आप जिस दशा में भी होते हैं और क़ुरआन में से जो कुछ भी पढ़ते हैं, तथा (ऐ ईमान वालो!) तुम जो भी कर्म करते हो, हम तुम्हें देख रहे होते हैं, जब तुम उसमें लगे होतो हो। और आपके पालनहार से कोई कण भर भी चीज़ न तो धरती में छिपी रहती है और न आकाश में, तथा न उससे कोई छोटी चीज़ है और न बड़ी, परंतु एक स्पष्ट पुस्तक में मौजूद है।"},{"a":62,"ar":"أَلَآ إِنَّ أَوْلِيَآءَ ٱللَّهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ","en":"Unquestionably, [for] the allies of Allāh there will be no fear concerning them, nor will they grieve -","ur":"سن رکھو کہ جو خدا کے دوست ہیں ان کو نہ کچھ خوف ہوگا اور نہ وہ غمناک ہوں گے","hi":"सुन लो! निःसंदेह अल्लाह के मित्रों को न कोई भय है और न वे शोकाकुल होंगे।"},{"a":63,"ar":"ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ","en":"Those who believed and were fearing Allāh.","ur":"(یعنی) جو لوگ ایمان لائے اور پرہیزگار رہے","hi":"वे लोग जो ईमान लाए और अल्लाह से डरते थे।"},{"a":64,"ar":"لَهُمُ ٱلْبُشْرَىٰ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْـَٔاخِرَةِ ۚ لَا تَبْدِيلَ لِكَلِمَـٰتِ ٱللَّهِ ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ","en":"For them are good tidings in the worldly life and in the Hereafter. No change is there in the words [i.e., decrees] of Allāh. That is what is the great attainment.","ur":"ان کے لیے دنیا کی زندگی میں بھی بشارت ہے اور آخرت میں بھی۔ خدا کی باتیں بدلتی نہیں۔ یہی تو بڑی کامیابی ہے","hi":"उन्हीं के लिए सांसारिक जीवन में शुभ सूचना है और आख़िरत में भी। अल्लाह की बातों के लिए कोई बदलाव नहीं है। यही बहुत बड़ी सफलता है।"},{"a":65,"ar":"وَلَا يَحْزُنكَ قَوْلُهُمْ ۘ إِنَّ ٱلْعِزَّةَ لِلَّهِ جَمِيعًا ۚ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ","en":"And let not their speech grieve you. Indeed, honor [due to power] belongs to Allāh entirely. He is the Hearing, the Knowing.","ur":"اور (اے پیغمبر) ان لوگوں کی باتوں سے آزردہ نہ ہونا (کیونکہ) عزت سب خدا ہی کی ہے وہ (سب کچھ) سنتا (اور) جانتا ہے","hi":"तथा (ऐ नबी!) आपको उनकी बात दुःखी न करे। निःसंदेह सारा प्रभुत्व अल्लाह ही के लिए है। वही सब कुछ सुनने वाला, सब कुछ जानने वाला है।"},{"a":66,"ar":"أَلَآ إِنَّ لِلَّهِ مَن فِى ٱلسَّمَـٰوَٰتِ وَمَن فِى ٱلْأَرْضِ ۗ وَمَا يَتَّبِعُ ٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ شُرَكَآءَ ۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ","en":"Unquestionably, to Allāh belongs whoever is in the heavens and whoever is on the earth. And those who invoke other than Allāh do not [actually] follow [His] \"partners.\" They follow not except assumption, and they are not but misjudging.","ur":"سن رکھو کہ جو مخلوق آسمانوں میں ہے اور جو زمین میں ہے سب خدا کے (بندے اور اس کے مملوک) ہیں۔ اور یہ جو خدا کے سوا (اپنے بنائے ہوئے) شریکوں کو پکارتے ہیں۔ وہ (کسی اور چیز کے) پیچھے نہیں چلتے۔ صرف ظن کے پیچھے چلتے ہیں اور محض اٹکلیں دوڑا رہے ہیں","hi":"सुन लो! निःसंदेह अल्लाह ही के लिए है जो कोई आसमानों में है और जो कोई ज़मीन में है और जो अल्लाह के सिवा दूसरे साझीदारों को पुकारते हैं, वे किस चीज़ की पैरवी कर रहे हैंॽ वे केवल अनुमान की पैरवी कर रहे हैं और वे मात्र अटकलें लगा रहे हैं।"},{"a":67,"ar":"هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِتَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يَسْمَعُونَ","en":"It is He who made for you the night to rest therein and the day, giving sight. Indeed in that are signs for a people who listen.","ur":"وہی تو ہے جس نے تمہارے لیے رات بنائی تاکہ اس میں آرام کرو اور روز روشن بنایا ( تاکہ اس میں کام کرو) جو لوگ (مادہٴ) سماعت رکھتے ہیں ان کے لیے ان میں نشانیاں ہیں","hi":"वही है, जिसने तुम्हारे लिए रात बनाई, ताकि उसमें आराम करो और दिन को प्रकाशमान बनाया। निःसंदेह इसमें उन लोगों के लिए बहुत-सी निशानियाँ हैं, जो सुनते हैं।"},{"a":68,"ar":"قَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًا ۗ سُبْحَـٰنَهُۥ ۖ هُوَ ٱلْغَنِىُّ ۖ لَهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ إِنْ عِندَكُم مِّن سُلْطَـٰنٍۭ بِهَـٰذَآ ۚ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ","en":"They have said, \"Allāh has taken a son.\" Exalted is He; He is the [one] Free of need. To Him belongs whatever is in the heavens and whatever is in the earth. You have no authority for this [claim]. Do you say about Allāh that which you do not know?","ur":"(بعض لوگ) کہتے ہیں کہ خدا نے بیٹا بنا لیا ہے۔ اس کی ذات (اولاد سے) پاک ہے (اور) وہ بےنیاز ہے۔ جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے وہ سب اسی کا ہے (اے افتراء پردازو) تمہارے پاس اس (قول باطل) کی کوئی دلیل نہیں ہے۔ تم خدا کی نسبت ایسی بات کیوں کہتے ہو جو جانتے نہیں","hi":"उन्होंने कहा कि अल्लाह ने कोई औलाद बना रखी है। वह पवित्र है, वह निस्पृह है। जो कुछ आकाशों में है और जो कुछ धरती में है, उसी का है।तुम्हारे पास इसका कोई प्रमाण नहीं है। क्या तुम अल्लाह के विषय में ऐसी बात कहते हो, जिसे तुम नहीं जानते?"},{"a":69,"ar":"قُلْ إِنَّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ لَا يُفْلِحُونَ","en":"Say, \"Indeed, those who invent falsehood about Allāh will not succeed.\"","ur":"کہہ دو جو لوگ خدا پر جھوٹ بہتان باندھتے ہیں فلاح نہیں پائیں گے","hi":"आप कह दें : निःसंदेह जो लोग अल्लाह पर झूठ गढ़ते हैं, वे सफल नहीं होंगे।"},{"a":70,"ar":"مَتَـٰعٌ فِى ٱلدُّنْيَا ثُمَّ إِلَيْنَا مَرْجِعُهُمْ ثُمَّ نُذِيقُهُمُ ٱلْعَذَابَ ٱلشَّدِيدَ بِمَا كَانُوا۟ يَكْفُرُونَ","en":"[For them is brief] enjoyment in this world; then to Us is their return; then We will make them taste the severe punishment because they used to disbelieve.","ur":"(ان کے لیے جو) فائدے ہیں دنیا میں (ہیں) پھر ان کو ہماری ہی طرف لوٹ کر آنا ہے۔ اس وقت ہم ان کو شدید عذاب (کے مزے) چکھائیں گے کیونکہ کفر (کی باتیں) کیا کرتے تھے","hi":"दुनिया में थोड़ा-सा फ़ायदा है, फिर हमारी ही तरफ़ उनकी वापसी है, फिर हम उन्हें बहुत सख़्त अज़ाब चखाएँगे, उसके कारण जो वे कुफ़्र करते थे।"},{"a":71,"ar":"۞ وَٱتْلُ عَلَيْهِمْ نَبَأَ نُوحٍ إِذْ قَالَ لِقَوْمِهِۦ يَـٰقَوْمِ إِن كَانَ كَبُرَ عَلَيْكُم مَّقَامِى وَتَذْكِيرِى بِـَٔايَـٰتِ ٱللَّهِ فَعَلَى ٱللَّهِ تَوَكَّلْتُ فَأَجْمِعُوٓا۟ أَمْرَكُمْ وَشُرَكَآءَكُمْ ثُمَّ لَا يَكُنْ أَمْرُكُمْ عَلَيْكُمْ غُمَّةً ثُمَّ ٱقْضُوٓا۟ إِلَىَّ وَلَا تُنظِرُونِ","en":"And recite to them the news of Noah, when he said to his people, \"O my people, if my residence and my reminding of the signs of Allāh has become burdensome upon you - then I have relied upon Allāh. So resolve upon your plan and [call upon] your associates. Then let not your plan be obscure to you. Then carry it out upon me and do not give me respite.","ur":"اور ان کو نوح کا قصہ پڑھ کر سنادو۔ جب انہوں نے اپنی قوم سے کہا کہ اے قوم! اگر تم کو میرا تم میں رہنا اور خدا کی آیتوں سے نصیحت کرنا ناگوار ہو تو میں خدا پر بھروسہ رکھتا ہوں۔ تم اپنے شریکوں کے ساتھ مل کر ایک کام (جو میرے بارے میں کرنا چاہو) مقرر کرلو اور وہ تمہاری تمام جماعت (کو معلوم ہوجائے اور کسی) سے پوشیدہ نہ رہے اور پھر وہ کام میرے حق میں کر گزرو اور مجھے مہلت نہ دو","hi":"तथा उन्हें नूह का समाचार सुनाएँ, जब उन्होंने अपनी जाति से कहा : ऐ मेरी जाति के लोगो! यदि मेरा खड़ा होना और अल्लाह की आयतों के द्वारा नसीहत करना तुमपर भारी पड़ गया, तो मैंने अल्लाह ही पर भरोसा किया है। अतः तुम अपना मामला अपने साझीदारों के साथ मिलकर पक्का कर लो, फिर तुम्हारा मामला तुमपर किसी तरह रहस्य न रहे। फिर (जो करना हो) मेरे साथ कर डालो और मुझे मोहलत न दो।"},{"a":72,"ar":"فَإِن تَوَلَّيْتُمْ فَمَا سَأَلْتُكُم مِّنْ أَجْرٍ ۖ إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ ۖ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُسْلِمِينَ","en":"And if you turn away [from my advice] - then no payment have I asked of you. My reward is only from Allāh, and I have been commanded to be of the Muslims [i.e., those who submit to Allāh].\"","ur":"اور اگر تم نے منہ پھیر لیا تو (تم جانتے ہو کہ) میں نے تم سے کچھ معاوضہ نہیں مانگا۔ میرا معاوضہ تو خدا کے ذمے ہے۔ اور مجھے حکم ہوا ہے کہ میں فرمانبرداروں میں رہوں","hi":"फिर यदि तुम मुँह फेर लो, तो मैंने तुमसे कोई पारिश्रमिक नहीं माँगा, मेरा पारिश्रमिक तो अल्लाह के ज़िम्मे है और मुझे आदेश दिया गया है कि मैं आज्ञाकारियों में से हो जाऊँ।"},{"a":73,"ar":"فَكَذَّبُوهُ فَنَجَّيْنَـٰهُ وَمَن مَّعَهُۥ فِى ٱلْفُلْكِ وَجَعَلْنَـٰهُمْ خَلَـٰٓئِفَ وَأَغْرَقْنَا ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا ۖ فَٱنظُرْ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُنذَرِينَ","en":"And they denied him, so We saved him and those with him in the ship and made them successors, and We drowned those who denied Our signs. Then see how was the end of those who were warned.","ur":"لیکن ان لوگوں نے ان کی تکذیب کی تو ہم نے ان کو اور جو لوگ ان کے ساتھ کشتی میں سوار تھے سب کو (طوفان سے) بچا لیا اور انہیں (زمین میں) خلیفہ بنادیا اور جن لوگوں نے ہماری آیتوں کو جھٹلایا ان کو غرق کر دیا تو دیکھ لو کہ جو لوگ ڈرائے گئے تھے ان کا کیا انجام ہوا","hi":"किंतु उन्होंने उसे झुठला दिया, तो हमने उसे और उन लोगों को जो उसके साथ कश्ती में थे बचा लिया और उन्हें उत्तराधिकारी बना दिया और उन लोगों को डुबो दिया जिन्होंने हमारी आयतों को झुठलाया था। तो देखिए उन लोगों का परिणाम कैसा हुआ जिन्हें डराया गया था।"},{"a":74,"ar":"ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِۦ رُسُلًا إِلَىٰ قَوْمِهِمْ فَجَآءُوهُم بِٱلْبَيِّنَـٰتِ فَمَا كَانُوا۟ لِيُؤْمِنُوا۟ بِمَا كَذَّبُوا۟ بِهِۦ مِن قَبْلُ ۚ كَذَٰلِكَ نَطْبَعُ عَلَىٰ قُلُوبِ ٱلْمُعْتَدِينَ","en":"Then We sent after him messengers to their peoples, and they came to them with clear proofs. But they were not to believe in that which they had denied before. Thus We seal over the hearts of the transgressors.","ur":"پھر نوح کے بعد ہم نے اور پیغمبر اپنی اپنی قوم کی طرف بھیجے۔ تو وہ ان کے پاس کھلی نشانیاں لے کر آئے۔ مگر وہ لوگ ایسے نہ تھے کہ جس چیز کی پہلے تکذیب کرچکے تھے اس پر ایمان لے آتے۔ اسی طرح ہم زیادتی کرنے والوں کے دلوں پر مہر لگا دیتے ہیں","hi":"फिर उसके बाद हमने कई रसूल उनकी जाति की ओर भेजे, तो वे उनके पास खुली निशानियाँ लेकर आए। पर वे ऐसे न थे कि जिसे वे पहले झुठला चुके थे, उसपर ईमान लाते। इसी तरह हम सीमा से आगे बढ़ने वालों के दिलों पर मुहर लगा देते हैं।"},{"a":75,"ar":"ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِم مُّوسَىٰ وَهَـٰرُونَ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ بِـَٔايَـٰتِنَا فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًا مُّجْرِمِينَ","en":"Then We sent after them Moses and Aaron to Pharaoh and his establishment with Our signs, but they behaved arrogantly and were a criminal people.","ur":"پھر ان کے بعد ہم نے موسیٰ اور ہارون کو اپنی نشانیاں دے کر فرعون اور اس کے سرداروں کے پاس بھیجا تو انہوں نے تکبر کیا اور وہ گنہگار لوگ تھے","hi":"फिर उनके बाद हमने मूसा और हारून को अपनी निशानियों के साथ फ़िरऔन और उसके सरदारों के पास भेजा, तो उन्होंने बहुत घमंड किया और वे अपराधी लोग थे।"},{"a":76,"ar":"فَلَمَّا جَآءَهُمُ ٱلْحَقُّ مِنْ عِندِنَا قَالُوٓا۟ إِنَّ هَـٰذَا لَسِحْرٌ مُّبِينٌ","en":"So when there came to them the truth from Us, they said, \"Indeed, this is obvious magic.\"","ur":"تو جب ان کے پاس ہمارے ہاں سے حق آیا تو کہنے لگے کہ یہ تو صریح جادو ہے","hi":"अतः जब उनके पास हमारी ओर से सत्य आया, तो उन्होंने कहा कि : नि:संदेह यह तो खुला जादू है।"},{"a":77,"ar":"قَالَ مُوسَىٰٓ أَتَقُولُونَ لِلْحَقِّ لَمَّا جَآءَكُمْ ۖ أَسِحْرٌ هَـٰذَا وَلَا يُفْلِحُ ٱلسَّـٰحِرُونَ","en":"Moses said, \"Do you say [thus] about the truth when it has come to you? Is this magic? But magicians will not succeed.\"","ur":"موسیٰ نے کہا کیا تم حق کے بارے میں جب وہ تمہارے پاس آیا یہ کہتے ہو کہ یہ جادو ہے۔ حالانکہ جادوگر فلاح نہیں پانے کے","hi":"मूसा (अलैहिस्सलाम) ने कहा : क्या तुम सत्य के बारे में (ऐसा) कहते हो, जब वह तुम्हारे पास आया? क्या जादू है यह? हालाँकि, जादूगर सफल नहीं होते।"},{"a":78,"ar":"قَالُوٓا۟ أَجِئْتَنَا لِتَلْفِتَنَا عَمَّا وَجَدْنَا عَلَيْهِ ءَابَآءَنَا وَتَكُونَ لَكُمَا ٱلْكِبْرِيَآءُ فِى ٱلْأَرْضِ وَمَا نَحْنُ لَكُمَا بِمُؤْمِنِينَ","en":"They said, \"Have you come to us to turn us away from that upon which we found our fathers and so that you two may have grandeur in the land? And we are not believers in you.\"","ur":"وہ بولے کیا تم ہمارے پاس اس لئے آئے ہو کہ جس (راہ) پر ہم اپنے باپ دادا کو پاتے رہے ہیں اس سے ہم کو پھیردو۔ اور (اس) ملک میں تم دونوں کی ہی سرداری ہوجائے اور ہم تم پر ایمان لانے والے نہیں ہیں","hi":"उन्होंने कहा : क्या तू हमारे पास इसलिए आया है कि हमको उस मार्ग से फेर दे जिसपर हमने अपने बाप-दादा को पाया है और इस देश में तुम दोनों की बड़ाई स्थापित हो जाए? और हम तुम दोनों को बिलकुल मानने वाले नहीं।"},{"a":79,"ar":"وَقَالَ فِرْعَوْنُ ٱئْتُونِى بِكُلِّ سَـٰحِرٍ عَلِيمٍ","en":"And Pharaoh said, \"Bring to me every learned magician.\"","ur":"اور فرعون نے حکم دیا کہ سب کامل فن جادوگروں کو ہمارے پاس لے آؤ","hi":"और फ़िरऔन ने कहा : हर कुशल जादूगर को मेरे पास लेकर आओ।"},{"a":80,"ar":"فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالَ لَهُم مُّوسَىٰٓ أَلْقُوا۟ مَآ أَنتُم مُّلْقُونَ","en":"So when the magicians came, Moses said to them, \"Throw down whatever you will throw.\"","ur":"جب جادوگر آئے تو موسیٰ نے ان سے کہا تم کو جو ڈالنا ہے ڈالو","hi":"फिर जब जादूगर आ गए, तो मूसा ने उनसे कहा : जो कुछ तुम फेंकने वाले हो, फेंको।"},{"a":81,"ar":"فَلَمَّآ أَلْقَوْا۟ قَالَ مُوسَىٰ مَا جِئْتُم بِهِ ٱلسِّحْرُ ۖ إِنَّ ٱللَّهَ سَيُبْطِلُهُۥٓ ۖ إِنَّ ٱللَّهَ لَا يُصْلِحُ عَمَلَ ٱلْمُفْسِدِينَ","en":"And when they had thrown, Moses said, \"What you have brought is [only] magic. Indeed, Allāh will expose its worthlessness. Indeed, Allāh does not amend the work of corrupters.","ur":"جب انہوں نے (اپنی رسیوں اور لاٹھیوں کو) ڈالا تو موسیٰ نے کہا کہ جو چیزیں تم (بنا کر) لائے ہو جادو ہے خدا اس کو بھی نیست ونابود کردے گا۔ خدا شریروں کے کام سنوارا نہیں کرتا","hi":"फिर जब उन्होंने फेंक दिया, तो मूसा ने कहा : तुम जो कुछ लाए हो, वह तो जादू है। निश्चय ही अल्लाह उसे शीघ्र ही निष्फल कर देगा। निःसंदेह अल्लाह बिगाड़ पैदा करने वालों का काम बनने नहीं देता।"},{"a":82,"ar":"وَيُحِقُّ ٱللَّهُ ٱلْحَقَّ بِكَلِمَـٰتِهِۦ وَلَوْ كَرِهَ ٱلْمُجْرِمُونَ","en":"And Allāh will establish the truth by His words, even if the criminals dislike it.\"","ur":"اور خدا اپنے حکم سے سچ کو سچ ہی کردے گا اگرچہ گنہگار برا ہی مانیں","hi":"और अल्लाह सत्य को, अपने शब्दों से, सत्य कर दिखाता है, यद्यपि अपराधियों को बुरा लगे।"},{"a":83,"ar":"فَمَآ ءَامَنَ لِمُوسَىٰٓ إِلَّا ذُرِّيَّةٌ مِّن قَوْمِهِۦ عَلَىٰ خَوْفٍ مِّن فِرْعَوْنَ وَمَلَإِي۟هِمْ أَن يَفْتِنَهُمْ ۚ وَإِنَّ فِرْعَوْنَ لَعَالٍ فِى ٱلْأَرْضِ وَإِنَّهُۥ لَمِنَ ٱلْمُسْرِفِينَ","en":"But no one believed Moses, except [some] offspring [i.e., youths] among his people, for fear of Pharaoh and his establishment that they would persecute them. And indeed, Pharaoh was haughty within the land, and indeed, he was of the transgressors.","ur":"تو موسیٰ پر کوئی ایمان نہ لایا۔ مگر اس کی قوم میں سے چند لڑکے (اور وہ بھی) فرعون اور اس کے اہل دربار سے ڈرتے ڈرتے کہ کہیں وہ ان کو آفت میں نہ پھنسا دے۔ اور فرعون ملک میں متکبر ومتغلب اور (کبر وکفر) میں حد سے بڑھا ہوا تھا","hi":"चुनाँचे मूसा पर उसकी जाति के कुछ युवाओं के सिवा कोई ईमान न लाया, (वह भी) फ़िरऔन और उनके सरदारों से डरते हुए कि कहीं वे उन्हें आज़माइश में न डाल दें। और निःसंदेह फ़िरऔन का धरती में बड़ा प्रभुत्व था और निश्चय ही वह हद पार करने वालों में से था।"},{"a":84,"ar":"وَقَالَ مُوسَىٰ يَـٰقَوْمِ إِن كُنتُمْ ءَامَنتُم بِٱللَّهِ فَعَلَيْهِ تَوَكَّلُوٓا۟ إِن كُنتُم مُّسْلِمِينَ","en":"And Moses said, \"O my people, if you have believed in Allāh, then rely upon Him, if you should be Muslims [i.e., submitting to Him].\"","ur":"اور موسیٰ نے کہا کہ بھائیو! اگر تم خدا پر ایمان لائے ہو تو اگر (دل سے) فرمانبردار ہو تو اسی پر بھروسہ رکھو","hi":"और मूसा ने कहा : ऐ मेरी जाति के लोगो! यदि तुम अल्लाह पर ईमान लाए हो, तो उसी पर भरोसा करो, यदि तुम आज्ञाकारी हो।"},{"a":85,"ar":"فَقَالُوا۟ عَلَى ٱللَّهِ تَوَكَّلْنَا رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلْقَوْمِ ٱلظَّـٰلِمِينَ","en":"So they said, \"Upon Allāh do we rely. Our Lord, make us not [objects of] trial for the wrongdoing people","ur":"تو وہ بولے کہ ہم خدا ہی پر بھروسہ رکھتے ہیں۔ اے ہمارے پروردگار ہم کو ظالم لوگوں کے ہاتھ سے آزمائش میں نہ ڈال","hi":"तो उन्होंने कहा : हमने अल्लाह ही पर भरोसा किया है। ऐ हमारे पालनहार! हमें अत्याचारी लोगों के लिए आज़माइश न बना।"},{"a":86,"ar":"وَنَجِّنَا بِرَحْمَتِكَ مِنَ ٱلْقَوْمِ ٱلْكَـٰفِرِينَ","en":"And save us by Your mercy from the disbelieving people.\"","ur":"اور اپنی رحمت سے قوم کفار سے نجات بخش","hi":"और हमें काफ़िर लोगों से अपनी रहमत से नजात दे।"},{"a":87,"ar":"وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰ وَأَخِيهِ أَن تَبَوَّءَا لِقَوْمِكُمَا بِمِصْرَ بُيُوتًا وَٱجْعَلُوا۟ بُيُوتَكُمْ قِبْلَةً وَأَقِيمُوا۟ ٱلصَّلَوٰةَ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ","en":"And We inspired to Moses and his brother, \"Settle your people in Egypt in houses and make your houses [facing the] qiblah and establish prayer and give good tidings to the believers.\"","ur":"اور ہم نے موسیٰ اور اس کے بھائی کی طرف وحی بھیجی کہ اپنے لوگوں کے لیے مصر میں گھر بناؤ اور اپنے گھروں کو قبلہ (یعنی مسجدیں) ٹھہراؤ اور نماز پڑھو۔ اور مومنوں کو خوشخبری سنادو","hi":"और हमने मूसा तथा उनके भाई (हारून) की ओर वह़्य भेजी कि अपनी जाति के लिए मिस्र में कुछ घरों को उपासनागृह नियत कर लो, और अपने घरों को क़िबले की तरफ़ बना लो, और नमाज़ क़ायम करो, और ईमान वालों को ख़ुशख़बरी दे दो।"},{"a":88,"ar":"وَقَالَ مُوسَىٰ رَبَّنَآ إِنَّكَ ءَاتَيْتَ فِرْعَوْنَ وَمَلَأَهُۥ زِينَةً وَأَمْوَٰلًا فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا رَبَّنَا لِيُضِلُّوا۟ عَن سَبِيلِكَ ۖ رَبَّنَا ٱطْمِسْ عَلَىٰٓ أَمْوَٰلِهِمْ وَٱشْدُدْ عَلَىٰ قُلُوبِهِمْ فَلَا يُؤْمِنُوا۟ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ","en":"And Moses said, \"Our Lord, indeed You have given Pharaoh and his establishment splendor and wealth in the worldly life, our Lord, that they may lead [men] astray from Your way. Our Lord, obliterate their wealth and harden their hearts so that they will not believe until they see the painful punishment.\"","ur":"اور موسیٰ نے کہا اے ہمارے پروردگار تو نے فرعون اور اس کے سرداروں کو دنیا کی زندگی میں (بہت سا) سازو برگ اور مال وزر دے رکھا ہے۔ اے پروردگار ان کا مال یہ ہے کہ تیرے رستے سے گمراہ کردیں۔ اے پروردگار ان کے مال کو برباد کردے اور ان کے دلوں کو سخت کردے کہ ایمان نہ لائیں جب تک عذاب الیم نہ دیکھ لیں","hi":"और मूसा ने कहा : ऐ हमारे पालनहार! तूने फ़िरऔन और उसके सरदारों को सांसारिक जीवन में शोभा-सामग्री तथा धन-संपत्ति प्रदान की है, ऐ हमारे पालनहार! ताकि वे (लोगों को) तेरे मार्ग से भटकाएँ। ऐ मेरे पालनहार! उनके धनों को मिटा दे और उनके दिलों को कसकर बाँध दे, ताकि वे ईमान न लाएँ, यहाँ तक कि दर्दनाक अज़ाब देख लें।"},{"a":89,"ar":"قَالَ قَدْ أُجِيبَت دَّعْوَتُكُمَا فَٱسْتَقِيمَا وَلَا تَتَّبِعَآنِّ سَبِيلَ ٱلَّذِينَ لَا يَعْلَمُونَ","en":"[Allāh] said, \"Your supplication has been answered.\" So remain on a right course and follow not the way of those who do not know.\"","ur":"خدا نے فرمایا کہ تمہاری دعا قبول کرلی گئی تو تم ثابت قدم رہنا اور بےعقلوں کے رستے نہ چلنا","hi":"अल्लाह ने कहा : निःसंदेह तुम दोनों की प्रार्थना स्वीकार कर ली गई। अतः तुम दोनों दृढ़ रहो और उन लोगों के मार्ग पर न चलो, जो नहीं जानते।"},{"a":90,"ar":"۞ وَجَـٰوَزْنَا بِبَنِىٓ إِسْرَٰٓءِيلَ ٱلْبَحْرَ فَأَتْبَعَهُمْ فِرْعَوْنُ وَجُنُودُهُۥ بَغْيًا وَعَدْوًا ۖ حَتَّىٰٓ إِذَآ أَدْرَكَهُ ٱلْغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَآ إِلَـٰهَ إِلَّا ٱلَّذِىٓ ءَامَنَتْ بِهِۦ بَنُوٓا۟ إِسْرَٰٓءِيلَ وَأَنَا۠ مِنَ ٱلْمُسْلِمِينَ","en":"And We took the Children of Israel across the sea, and Pharaoh and his soldiers pursued them in tyranny and enmity until, when drowning overtook him, he said, \"I believe that there is no deity except that in whom the Children of Israel believe, and I am of the Muslims.\"","ur":"اور ہم نے بنی اسرائیل کو دریا سے پار کردیا تو فرعون اور اس کے لشکر نے سرکشی اور تعدی سے ان کا تعاقب کیا۔ یہاں تک کہ جب اس کو غرق (کے عذاب) نے آپکڑا تو کہنے لگا کہ میں ایمان لایا کہ جس (خدا) پر بنی اسرائیل ایمان لائے ہیں اس کے سوا کوئی معبود نہیں اور میں فرمانبرداروں میں ہوں","hi":"और हमने बनी इसराईल को सागर पार करा दिया, तो फ़िरऔन और उसकी सेना ने सरकशी और ज़्यादती करते हुए उनका पीछा किया। यहाँ तक कि जब वह डूबने लगा, तो बोला : मैं ईमान ले आया कि निःसंदेह उसके सिवा कोई पूज्य नहीं, जिसपर बनी इसराईल ईमान लाए हैं और मैं आज्ञाकारियों में से हूँ।"},{"a":91,"ar":"ءَآلْـَٔـٰنَ وَقَدْ عَصَيْتَ قَبْلُ وَكُنتَ مِنَ ٱلْمُفْسِدِينَ","en":"Now? And you had disobeyed [Him] before and were of the corrupters?","ur":"(جواب ملا کہ) اب (ایمان لاتا ہے) حالانکہ تو پہلے نافرمانی کرتا رہا اور مفسد بنا رہا","hi":"क्या अब? हालाँकि निःसंदेह तूने इससे पहले अवज्ञा की और तू बिगाड़ पैदा करने वालों में से था।"},{"a":92,"ar":"فَٱلْيَوْمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنْ خَلْفَكَ ءَايَةً ۚ وَإِنَّ كَثِيرًا مِّنَ ٱلنَّاسِ عَنْ ءَايَـٰتِنَا لَغَـٰفِلُونَ","en":"So today We will save you in body that you may be to those who succeed you a sign. And indeed, many among the people, of Our signs, are heedless.","ur":"تو آج ہم تیرے بدن کو (دریا سے) نکال لیں گے تاکہ تو پچھلوں کے لئے عبرت ہو۔ اور بہت سے لوگ ہماری نشانیوں سے بےخبر ہیں","hi":"अतः आज हम तेरे शरीर को बचा लेंगे, ताकि तू अपने बाद आने वालों के लिए एक बड़ी निशानी बन जाए और निःसंदेह बहुत-से लोग हमारी निशानियों से निश्चय ग़ाफ़िल हैं।"},{"a":93,"ar":"وَلَقَدْ بَوَّأْنَا بَنِىٓ إِسْرَٰٓءِيلَ مُبَوَّأَ صِدْقٍ وَرَزَقْنَـٰهُم مِّنَ ٱلطَّيِّبَـٰتِ فَمَا ٱخْتَلَفُوا۟ حَتَّىٰ جَآءَهُمُ ٱلْعِلْمُ ۚ إِنَّ رَبَّكَ يَقْضِى بَيْنَهُمْ يَوْمَ ٱلْقِيَـٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ","en":"And We had certainly settled the Children of Israel in an agreeable settlement and provided them with good things. And they did not differ until [after] knowledge had come to them. Indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ.","ur":"اور ہم نے بنی اسرائیل کو رہنے کو عمدہ جگہ دی اور کھانے کو پاکیزہ چیزیں عطا کیں لیکن وہ باوجود علم ہونے کے اختلاف کرتے رہے۔ بےشک جن باتوں میں وہ اختلاف کرتے رہے ہیں تمہارا پروردگار قیامت کے دن ان میں ان باتوں کا فیصلہ کردے گا","hi":"और निःसंदेह हमने बनी इसराईल को सम्मानित ठिकाना दिया और उन्हें पाकीज़ा चीज़ों से जीविका प्रदान की। फिर उन्होंने आपस में मतभेद नहीं किया, यहाँ तक कि उनके पास ज्ञान आ गया। निःसंदेह आपका पालनहार क़ियामत के दिन उनके बीच उस चीज़ का निर्णय कर देगा, जिसमें वे मतभेद करते थे।"},{"a":94,"ar":"فَإِن كُنتَ فِى شَكٍّ مِّمَّآ أَنزَلْنَآ إِلَيْكَ فَسْـَٔلِ ٱلَّذِينَ يَقْرَءُونَ ٱلْكِتَـٰبَ مِن قَبْلِكَ ۚ لَقَدْ جَآءَكَ ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ","en":"So if you are in doubt, [O Muḥammad], about that which We have revealed to you, then ask those who have been reading the Scripture before you. The truth has certainly come to you from your Lord, so never be among the doubters.","ur":"اگر تم کو اس (کتاب کے) بارے میں جو ہم نے تم پر نازل کی ہے کچھ شک ہو تو جو لوگ تم سے پہلے کی (اُتری ہوئی) کتابیں پڑھتے ہیں ان سے پوچھ لو۔ تمہارے پروردگار کی طرف سے تمہارے پاس حق آچکا ہے تو تم ہرگز شک کرنے والوں میں نہ ہونا","hi":"फिर यदि आपको उसमें कुछ संदेह हो, जो हमने आपकी ओर उतारा है, तो उन लोगों से पूछ लें, जो आपसे पहले किताब पढ़ते हैं। निःसंदेह आपके पास आपके पालनहार की ओर से सत्य आ चुका है। अतः आप हरगिज़ संदेह करने वालों में से न हों।"},{"a":95,"ar":"وَلَا تَكُونَنَّ مِنَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِ ٱللَّهِ فَتَكُونَ مِنَ ٱلْخَـٰسِرِينَ","en":"And never be of those who deny the signs of Allāh and [thus] be among the losers.","ur":"اور نہ ان لوگوں میں ہونا جو خدا کی آیتوں کی تکذیب کرتے ہیں نہیں تو نقصان اٹھاؤ گے","hi":"तथा आप उन लोगों में कभी न होना, जिन्होंने अल्लाह की आयतों को झुठलाया, अन्यथा आप घाटा उठाने वालों में से हो जाएँगे।"},{"a":96,"ar":"إِنَّ ٱلَّذِينَ حَقَّتْ عَلَيْهِمْ كَلِمَتُ رَبِّكَ لَا يُؤْمِنُونَ","en":"Indeed, those upon whom the word [i.e., decree] of your Lord has come into effect will not believe,","ur":"جن لوگوں کے بارے میں خدا کا حکم (عذاب) قرار پاچکا ہے وہ ایمان نہیں لانے کے","hi":"निःसंदेह जिन लोगों के विरुद्ध आपके पालनहार का फ़ैसला सिद्ध हो चुका, वे ईमान नहीं लाएँगे।"},{"a":97,"ar":"وَلَوْ جَآءَتْهُمْ كُلُّ ءَايَةٍ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ","en":"Even if every sign should come to them, until they see the painful punishment.","ur":"جب تک کہ عذاب الیم نہ دیکھ لیں خواہ ان کے پاس ہر (طرح کی) نشانی آجائے","hi":"चाहे उनके पास हर निशानी आ जाए, यहाँ तक कि वे दर्दनाक अज़ाब देख लें।"},{"a":98,"ar":"فَلَوْلَا كَانَتْ قَرْيَةٌ ءَامَنَتْ فَنَفَعَهَآ إِيمَـٰنُهَآ إِلَّا قَوْمَ يُونُسَ لَمَّآ ءَامَنُوا۟ كَشَفْنَا عَنْهُمْ عَذَابَ ٱلْخِزْىِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَتَّعْنَـٰهُمْ إِلَىٰ حِينٍ","en":"Then has there not been a [single] city that believed so its faith benefited it except the people of Jonah? When they believed, We removed from them the punishment of disgrace in worldly life and gave them enjoyment [i.e., provision] for a time.","ur":"تو کوئی بستی ایسی کیوں نہ ہوئی کہ ایمان لاتی تو اس کا ایمان اسے نفع دیتا ہاں یونس کی قوم۔ جب ایمان لائی تو ہم نے دنیا کی زندگی میں ان سے ذلت کا عذاب دور کردیا اور ایک مدت تک (فوائد دنیاوی سے) ان کو بہرہ مند رکھا","hi":"तो कोई ऐसी बस्ती क्यों न हुई जो ईमान लाई हो, फिर उसके ईमान ने उसे लाभ पहुँचाया हो, सिवाए यूनुस की जाति के लोगों के। जब वे ईमान ले आए, तो हमने उनसे सांसारिक जीवन में अपमान की यातना को टाल दिया और उन्हें एक निश्चित समय तक लाभ उठाने का अवसर दे दिया।"},{"a":99,"ar":"وَلَوْ شَآءَ رَبُّكَ لَـَٔامَنَ مَن فِى ٱلْأَرْضِ كُلُّهُمْ جَمِيعًا ۚ أَفَأَنتَ تُكْرِهُ ٱلنَّاسَ حَتَّىٰ يَكُونُوا۟ مُؤْمِنِينَ","en":"And had your Lord willed, those on earth would have believed - all of them entirely. Then, [O Muḥammad], would you compel the people in order that they become believers?","ur":"اور اگر تمہارا پروردگار چاہتا تو جتنے لوگ زمین پر ہیں سب کے سب ایمان لے آتے۔ تو کیا تم لوگوں پر زبردستی کرنا چاہتے ہو کہ وہ مومن ہوجائیں","hi":"और यदि आपका पालनहार चाहता, तो निश्चय धरती में रहने वाले सभी लोग ईमान ले आते। तो क्या आप लोगों को बाध्य करेंगे कि वे मोमिन बन जाएँॽ"},{"a":100,"ar":"وَمَا كَانَ لِنَفْسٍ أَن تُؤْمِنَ إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَيَجْعَلُ ٱلرِّجْسَ عَلَى ٱلَّذِينَ لَا يَعْقِلُونَ","en":"And it is not for a soul [i.e., anyone] to believe except by permission of Allāh, and He will place defilement upon those who will not use reason.","ur":"حالانکہ کسی شخص کو قدرت نہیں ہے کہ خدا کے حکم کے بغیر ایمان لائے۔ اور جو لوگ بےعقل ہیں ان پر وہ (کفر وذلت کی) نجاست ڈالتا ہے","hi":"किसी प्राणी के लिए यह संभव नहीं है कि वह अल्लाह की अनुमति के बिना ईमान लाए और वह उन लोगों पर मलिनता डाल देता है, जो समझ नहीं रखते।"},{"a":101,"ar":"قُلِ ٱنظُرُوا۟ مَاذَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَمَا تُغْنِى ٱلْـَٔايَـٰتُ وَٱلنُّذُرُ عَن قَوْمٍ لَّا يُؤْمِنُونَ","en":"Say, \"Observe what is in the heavens and the earth.\" But of no avail will be signs or warners to a people who do not believe.","ur":"(ان کفار سے) کہو دیکھو تو زمین اور آسمانوں میں کیا کچھ ہے۔ مگر جو لوگ ایمان نہیں رکھتے ان کی نشانیاں اور ڈرواے کچھ کام نہیں آتے","hi":"(ऐ नबी!) उनसे कह दें : तुम देखो आकाशों और धरती में क्या कुछ है? तथा निशानियाँ और चेतावनियाँ उन लोगों के लिए किसी काम की नहीं हैं जो ईमान नहीं लाते।"},{"a":102,"ar":"فَهَلْ يَنتَظِرُونَ إِلَّا مِثْلَ أَيَّامِ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِهِمْ ۚ قُلْ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ","en":"So do they wait except for like [what occurred in] the days of those who passed on before them? Say, \"Then wait; indeed, I am with you among those who wait.\"","ur":"سو جیسے (برے) دن ان سے پہلے لوگوں پر گزر چکے ہیں اسی طرح کے (دنوں کے) یہ منتظر ہیں۔ کہہ دو کہ تم بھی انتظار کرو۔ میں بھی تمہارے ساتھ انتظار کرتا ہوں","hi":"तो क्या ये लोग उन लोगों के दिनों के समान (दिनों) की प्रतीक्षा कर रहे हैं, जो उनसे पहले गुज़र चुके हैंॽ आप कह दें : फिर प्रतीक्षा करो, निश्चय मैं भी तुम्हारे साथ प्रतीक्षा करने वालों में से हूँ।"},{"a":103,"ar":"ثُمَّ نُنَجِّى رُسُلَنَا وَٱلَّذِينَ ءَامَنُوا۟ ۚ كَذَٰلِكَ حَقًّا عَلَيْنَا نُنجِ ٱلْمُؤْمِنِينَ","en":"Then We will save Our messengers and those who have believed. Thus, it is an obligation upon Us that We save the believers.","ur":"اور ہم اپنے پیغمبروں کو اور مومنوں کو نجات دیتے رہے ہیں۔ اسی طرح ہمارا ذمہ ہے کہ مسلمانوں کو نجات دیں","hi":"फिर हम अपने रसूलों को और ईमान लाने वालों को बचा लेते हैं। इसी तरह हमपर हक़ है कि हम ईमान वालों को बचा लें।"},{"a":104,"ar":"قُلْ يَـٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمْ فِى شَكٍّ مِّن دِينِى فَلَآ أَعْبُدُ ٱلَّذِينَ تَعْبُدُونَ مِن دُونِ ٱللَّهِ وَلَـٰكِنْ أَعْبُدُ ٱللَّهَ ٱلَّذِى يَتَوَفَّىٰكُمْ ۖ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُؤْمِنِينَ","en":"Say, [O Muḥammad], \"O people, if you are in doubt as to my religion - then I do not worship those which you worship besides Allāh; but I worship Allāh, who causes your death. And I have been commanded to be of the believers","ur":"(اے پیغمبر) کہہ دو کہ لوگو اگر تم کو میرے دین میں کسی طرح کا شک ہو تو (سن رکھو کہ) جن لوگوں کی تم خدا کے سوا عبادت کرتے ہو میں ان کی عبادت نہیں کرتا۔ بلکہ میں خدا کی عبادت کرتا ہوں جو تمھاری روحیں قبض کرلیتا ہے اور مجھ کو یہی حکم ہوا ہے کہ ایمان لانے والوں میں ہوں","hi":"आप कह दें : ऐ लोगो! यदि तुम मेरे धर्म के बारे में किसी संदेह में हो, तो मैं उनकी इबादत नहीं करता, जिनकी तुम अल्लाह को छोड़कर इबादत करते हो, बल्कि मैं उस अल्लाह की इबादत करता हूँ, जो तुम्हें मौत देता है और मुझे आदेश दिया गया है कि मैं ईमान वालों में से जाऊँ।"},{"a":105,"ar":"وَأَنْ أَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًا وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ","en":"And [commanded], 'Direct your face [i.e., self] toward the religion, inclining to truth, and never be of those who associate others with Allāh;","ur":"اور یہ کہ (اے محمد سب سے) یکسو ہو کر دین (اسلام) کی پیروی کئے جاؤ۔ اور مشرکوں میں ہرگز نہ ہونا","hi":"और यह कि आप एकाग्र होकर अपना मुख इस धर्म की ओर सीधा रखें और कदापि बहुदेववादियों में से न हों।"},{"a":106,"ar":"وَلَا تَدْعُ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكَ وَلَا يَضُرُّكَ ۖ فَإِن فَعَلْتَ فَإِنَّكَ إِذًا مِّنَ ٱلظَّـٰلِمِينَ","en":"And do not invoke besides Allāh that which neither benefits you nor harms you, for if you did, then indeed you would be of the wrongdoers.'\"","ur":"اور خدا کو چھوڑ کر ایسی چیز کو نہ پکارنا جو نہ تمہارا کچھ بھلا کرسکے اور نہ کچھ بگاڑ سکے۔ اگر ایسا کرو گے تو ظالموں میں ہوجاؤ گے","hi":"और अल्लाह को छोड़कर उसे न पुकारें, जो न आपको लाभ पहुँचाए और न आपको हानि पहुँचा सके। फिर यदि आपने ऐसा किया, तो निश्चय ही आप उस समय अत्याचारियों में से हो जाएँगे।"},{"a":107,"ar":"وَإِن يَمْسَسْكَ ٱللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ ۖ وَإِن يُرِدْكَ بِخَيْرٍ فَلَا رَآدَّ لِفَضْلِهِۦ ۚ يُصِيبُ بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۚ وَهُوَ ٱلْغَفُورُ ٱلرَّحِيمُ","en":"And if Allāh should touch you with adversity, there is no remover of it except Him; and if He intends for you good, then there is no repeller of His bounty. He causes it to reach whom He wills of His servants. And He is the Forgiving, the Merciful.","ur":"اور اگر خدا تم کو کوئی تکلیف پہنچائے تو اس کے سوا اس کا کوئی دور کرنے والا نہیں اور اگر تم سے بھلائی کرنی چاہے تو اس کے فضل کو کوئی روکنے والا نہیں۔ وہ اپنے بندوں میں سے جسے چاہتا ہے فائدہ پہنچاتا ہے اور وہ بخشنے والا مہربان ہے","hi":"और यदि अल्लाह आपको कोई कष्ट पहुँचाए, तो उसके सिवा कोई उसे दूर करने वाला नहीं और यदि वह आपके लिए कोई भलाई चाहे, तो उसके अनुग्रह को कोई हटाने वाला नहीं। वह उसे अपने बंदों में से जिसे चाहता है, प्रदान करता है तथा वही बड़ा क्षमाशील, अत्यंत दयावान् है।"},{"a":108,"ar":"قُلْ يَـٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُمُ ٱلْحَقُّ مِن رَّبِّكُمْ ۖ فَمَنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ ۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا ۖ وَمَآ أَنَا۠ عَلَيْكُم بِوَكِيلٍ","en":"Say, \"O mankind, the truth has come to you from your Lord, so whoever is guided is only guided for [the benefit of] his soul, and whoever goes astray only goes astray [in violation] against it. And I am not over you a manager.\"","ur":"کہہ دو کہ لوگو تمہارے پروردگار کے ہاں سے تمہارے پاس حق آچکا ہے تو جو کوئی ہدایت حاصل کرتا ہے تو ہدایت سے اپنے ہی حق میں بھلائی کرتا ہے۔ اور جو گمراہی اختیار کرتا ہے تو گمراہی سے اپنا ہی نقصان کرتا ہے۔ اور میں تمہارا وکیل نہیں ہوں","hi":"(ऐ नबी!) आप कह दें : ऐ लोगो! निःसंदेह तुम्हारे पालनहार की ओर से तुम्हारे पास सत्य आ गया है। तो जो सीधे मार्ग पर आया, तो वह अपने आप ही के लिए मार्ग पर आता है और जो पथभ्रष्ट हुआ, तो वह अपने आप ही पर पथभ्रष्ट होता है और मैं तुमपर हरगिज़ कोई निरीक्षक नहीं हूँ।"},{"a":109,"ar":"وَٱتَّبِعْ مَا يُوحَىٰٓ إِلَيْكَ وَٱصْبِرْ حَتَّىٰ يَحْكُمَ ٱللَّهُ ۚ وَهُوَ خَيْرُ ٱلْحَـٰكِمِينَ","en":"And follow what is revealed to you, [O Muḥammad], and be patient until Allāh will judge. And He is the best of judges.","ur":"اور (اے پیغمبر) تم کو جو حکم بھیجا جاتا ہے اس کی پیروی کئے جاؤ اور (تکلیفوں پر) صبر کرو یہاں تک کہ خدا فیصلہ کردے۔ اور وہ سب سے بہتر فیصلہ کرنے والا ہے","hi":"और आप उसी का अनुसरण करें, जो आपकी ओर वह़्य की जाती है और धैर्य से काम लें, यहाँ तक कि अल्लाह फ़ैसला कर दे और वह सब फ़ैसला करने वालों से बेहतर है।"}],"tlx":{"hi":"यूनुस","ur":"یونس"}};
